  VALUES
    (2401, 'SUB-2401', 'SBM5', '¿EN QUE CASOS, EL JUEZ RESOLVERÁ LA INCAUTACIÓN O EL DECOMISO DEL DINERO, BIENES, EFECTOS O GANANCIAS INVOLUCRADOS, CONFORME A LO PREVISTO EN EL ARTÍCULO 102 DEL CÓDIGO PENAL?:.', 'EN TODOS LOS CASOS.', 'ART. 9', '185093'),
    (2402, 'SUB-2402', 'SBM5', 'EL LAVADO DE ACTIVOS ES UN DELITO AUTÓNOMO POR LO QUE PARA SU INVESTIGACIÓN, PROCESAMIENTO Y SANCIÓN NO ES NECESARIO QUE LAS ACTIVIDADES CRIMINALES QUE PRODUJERON EL DINERO, LOS BIENES, EFECTOS O GANANCIAS, HAYAN SIDO DESCUBIERTAS, SE ENCUENTREN SOMETIDAS A INVESTIGACIÓN, PROCESO JUDICIAL O HAYAN SIDO PREVIAMENTE OBJETO DE:.', 'PRUEBA O CONDENA.', 'ART. 10 Primer Párrafo', '185094'),
    (2403, 'SUB-2403', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO, CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'MINERIA ILEGAL.', 'ART. 10 Segundo Párrafo', '185095'),
    (2404, 'SUB-2404', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'TRÁFICO ILÍCITO DE DROGAS.', 'ART. 10 Segundo Párrafo', '185096'),
    (2405, 'SUB-2405', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'TERRORISMO', 'ART. 10 Segundo Párrafo', '185097'),
    (2406, 'SUB-2406', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO:.', 'DELITOS CONTRA LA ADMINISTRACIÓN PÚBLICA.', 'ART. 10 Segundo Párrafo', '185098'),
    (2407, 'SUB-2407', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'SECUESTRO', 'ART. 10 Segundo Párrafo', '185099'),
    (2408, 'SUB-2408', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'PROXENETISMO', 'ART. 10 Segundo Párrafo', '185100'),
    (2409, 'SUB-2409', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'TRATA DE PERSONAS.', 'ART. 10 Segundo Párrafo', '185101'),
    (2410, 'SUB-2410', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'TRÁFICO ILÍCITO DE ARMAS.', 'ART. 10 Segundo Párrafo', '185102'),
    (2411, 'SUB-2411', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'TRÁFICO ILÍCITO DE MIGRANTES.', 'ART. 10 Segundo Párrafo DL 1106 - Lucha contra el lavado de activos', '185103'),
    (2412, 'SUB-2412', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO:.', 'DELITOS TRIBUTARIOS', 'ART. 10 Segundo Párrafo', '185104'),
    (2413, 'SUB-2413', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO, CORRESPONDE A ACTIVIDADES CRIMINALES COMO LOS DELITOS DE:.', 'EXTORSIÓN', 'ART. 10 Segundo Párrafo', '185105'),
    (2414, 'SUB-2414', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO:.', 'ROBO.', 'ART. 10 Segundo Párrafo', '185106'),
    (2415, 'SUB-2415', 'SBM5', 'EL CONOCIMIENTO DEL ORIGEN ILÍCITO QUE TIENE O QUE DEBÍA PRESUMIR EL AGENTE DE LOS DELITOS QUE CONTEMPLA EL PRESENTE DECRETO LEGISLATIVO CORRESPONDE A ACTIVIDADES CRIMINALES COMO:.', 'DELITOS ADUANEROS.', 'ART. 10 Segundo Párrafo', '185107'),
    (2416, 'SUB-2416', 'SBM5', 'TAMBIÉN PODRÁ SER CONSIDERADO AUTOR DEL DELITO Y POR TANTO SUJETO DE INVESTIGACIÓN Y JUZGAMIENTO POR LAVADO DE ACTIVOS, EL QUE:.', 'EJECUTÓ O PARTICIPÓ EN LAS ACTIVIDADES CRIMINALES GENERADORAS DEL DINERO, BIENES, EFECTOS O GANANCIAS.', 'ART. 10 Último Párrafo', '185108'),
    (2417, 'SUB-2417', 'SBM5', 'EN LOS CASOS DE MINERÍA ILEGAL, TRÁFICO ILÍCITO DE DROGAS, TERRORISMO, SECUESTRO, EXTORSIÓN O TRATA DE PERSONAS NO PODRÁN ACOGERSE A LOS BENEFICIOS PENITENCIARIOS DE:. DL 1106 - Lucha contra el lavado de activos', 'REDENCIÓN DE LA PENA POR EL TRABAJO Y LA EDUCACIÓN.', 'ART. 11', '185109'),
    (2418, 'SUB-2418', 'SBM5', 'PROHIBICION DE BENEFICIOS PENITENCIARIOS, EN LOS CASOS QUIENES INCURRAN EN LA AGRAVANTE CONTEMPLADA EN EL ART4 DEL PRESENTE DL 1106, NO PODRÁN ACOGERSE A LOS BENEFICIOS PENITENCIARIOS DE:.', 'SEMILIBERTAD.', 'ART. 11', '185110'),
    (2419, 'SUB-2419', 'SBM5', 'LAS FUERZAS ARMADAS EN EL MARCO DE LO DISPUESTO POR LA CONSTITUCIÓN POLÍTICA DEL PERÚ, DECRETO LEGISLATIVO 1100 Y EL PRESENTE DECRETO LEGISLATIVO, PARA ASEGURAR EL CUMPLIMIENTO DE LA PRESENTE NORMA COLABORARÁ CON:.', 'EL MINISTERIO PÚBLICO.', 'ART. 16 Segundo Párrafo', '185115'),
    (2420, 'SUB-2420', 'SBM5', 'LA INTERVENCIÓN DE LAS FUERZAS ARMADAS NO IMPLICA EN MODO ALGUNO LA RESTRICCIÓN, SUSPENSIÓN, NI AFECTACIÓN DE LOS DERECHOS FUNDAMENTALES CONSAGRADOS EN:.', 'LA CONSTITUCIÓN POLÍTICA DEL PERÚ.', 'ART. 16 Tercer Párrafo', '185116'),
    (2421, 'SUB-2421', 'SBM5', 'LAS INSTIUCIONES QUE ESTARÁN OBLIGADAS A ADOPTAR MEDIDAS DE CONTROL APROPIADAS Y SUFICIENTES, ORIENTADAS A EVITAR QUE EN LA REALIZACIÓN DE SUS OPERACIONES SE PRODUZCA EL OCULTAMIENTO, MANEJO, INVERSIÓN O APROVECHAMIENTO EN CUALQUIER FORMA DE DINERO U OTROS BIENES PROVENIENTES DE LA MINERÍA ILEGAL, ASÍ COMO DE CUALQUIER OTRA ACTIVIDAD DE CRIMEN ORGANIZADO O DESTINADOS A SU FINANCIACIÓN:.', 'LAS INSTITUCIONES SOMETIDAS AL CONTROL Y SUPERVISIÓN DE LA SUPERINTENDENCIA BANCA, SEGUROS Y ADMINISTRADORAS PRIVADAS DE FONDOS DE PENSIONES.', 'DISP. COMP. FINAL - PRIMERA', '185117'),
    (2422, 'SUB-2422', 'SBM5', 'LOS SUJETOS OBLIGADOS ESTABLECIDOS A TRAVÉS DE LA LEY 27693, DEBERÁN REPORTAR BAJO RESPONSABILIDAD, DE FORMA INMEDIATA Y SUFICIENTE A LA:. DL 1106 - Lucha contra el lavado de activos', 'UNIDAD DE INTELIGENCIA FINANCIERA.', 'DISP. COMP. FINAL - PRIMERA', '185118'),
    (2423, 'SUB-2423', 'SBM5', 'LA ADMINISTRACIÓN DEL DINERO, BIENES, EFECTOS O GANANCIAS ILEGALES QUE HAYAN SIDO INCAUTADOS POR LOS DELITOS PREVISTOS EN EL PRESENTE DECRETO LEGISLATIVO; SE ADECUARÁ A LO ESTABLECIDO EN:.', 'LAS DISPOSICIONES SOBRE LA MATERIA PREVISTAS EN LA LEGISLACIÓN VIGENTE.', 'DISP. COMP. FINAL - SEGUNDA', '185119'),
    (2424, 'SUB-2424', 'SBM5', 'EL MINISTERIO PÚBLICO DISEÑARÁ Y PONDRÁ EN EJECUCIÓN UN PROGRAMA DE CAPACITACIÓN CONTRA EL LAVADO DE ACTIVOS VINCULADOS A:.', 'LA MINERÍA ILEGAL Y OTRAS FORMAS DE CRIMEN ORGANIZADO.', 'DISP. COMP. FINAL - TERCERA', '185121'),
    (2425, 'SUB-2425', 'SBM5', '¿QUÉ ENTIDAD DISEÑARÁ Y PONDRÁ EN EJECUCIÓN UN PROGRAMA DE CAPACITACIÓN CONTRA EL LAVADO DE ACTIVOS VINCULADOS A LA MINERÍA ILEGAL Y OTRAS FORMAS DE CRIMEN ORGANIZADO?', 'EL MINISTERIO PÚBLICO.', 'DISP. COMP. FINAL - TERCERA', '185122'),
    (2426, 'SUB-2426', 'SBM5', '¿QUIÉNES BRINDAN SU COLABORACIÓN A LA UNIDAD DE INTELIGENCIA FINANCIERA DEL PERÚ (UIF - PERÚ) PARA EL CUMPLIMIENTO DE SU MISIÓN INSTITUCIONAL?', 'LAS ENTIDADES DEL ESTADO, EN LOS ÁMBITOS NACIONAL, REGIONAL Y LOCAL, Y LAS EMPRESAS EN LAS QUE EL ESTADO TIENE PARTICIPACIÓN.', 'DISP. COMP. FINAL - CUARTA', '185123'),
    (2427, 'SUB-2427', 'SBM5', 'LAS ENTIDADES DEL ESTADO, EN LOS ÁMBITOS NACIONAL, REGIONAL Y LOCAL, Y LAS EMPRESAS EN LAS QUE EL ESTADO TIENE PARTICIPACIÓN PARA EL CUMPLIMIENTO DE SU MISIÓN INSTITUCIONAL, PROPORCIONANDO INFORMACIÓN Y CUALQUIER OTRA FORMA DE COOPERACIÓN NECESARIA PARA COMBATIR EL DELITO DE LAVADO DE ACTIVOS, BRINDAN SU COLABORACIÓN:.', 'A LA UNIDAD DE INTELIGENCIA FINANCIERA DEL PERÚ (UIF - PERÚ).', 'DISP. COMP. FINAL - CUARTA', '185124'),
    (2428, 'SUB-2428', 'SBM5', '¿CON QUÉ INSTITUCIÓN LA UIF-PERÚ MANTENDRÁ RELACIONES DE COORDINACIÓN A FIN DE LOGRAR UNA MAYOR EFICACIA EN LA LUCHA CONTRA EL DELITO DE LAVADO DE ACTIVOS, VINCULADO ESPECIALMENTE A LA MINERÍA ILEGAL U OTRAS FORMAS DE CRIMEN ORGANIZADO?', 'CON EL CONSEJO DE DEFENSA JURÍDICA DEL ESTADO.', 'DISP. COMP. FINAL - CUARTA', '185125'),
    (2429, 'SUB-2429', 'SBM5', 'LA UIF - PERÚ MANTENDRÁ RELACIONES DE COORDINACIÓN CON EL CONSEJO DE DEFENSA JURÍDICA DEL ESTADO A FIN DE:.', 'LOGRAR UNA MAYOR EFICACIA EN LA LUCHA CONTRA EL DELITO DE LAVADO DE ACTIVOS, VINCULADO ESPECIALMENTE A LA MINERÍA ILEGAL U OTRAS FORMAS DE CRIMEN ORGANIZADO.', 'DISP. COMP. FINAL - CUARTA', '185126'),
    (2430, 'SUB-2430', 'SBM5', 'LOS GASTOS QUE DEMANDE LA APLICACIÓN DEL PRESENTE DECRETO LEGISLATIVO, SE EJECUTAN CON CARGO A LOS PRESUPUESTOS:.', 'INSTITUCIONALES DE LAS ENTIDADES COMPETENTES.', 'DISP. COMP. FINAL - QUINTA', '185127'),
    (2431, 'SUB-2431', 'SBM5', 'PARA EL CUMPLIMIENTO DE LO DISPUESTO EN EL ARTÍCULO 14 DE LA LEY 27693, LEY QUE CREA LA UNIDAD DE INTELIGENCIA FINANCIERA - PERÚ, LOS SUJETOS OBLIGADOS DEBEN INFORMAR A LA UNIDAD DE INTELIGENCIA FINANCIERA EN EL PLAZO DE:.', 'NOVENTA (90) DÍAS NATURALES.', 'DISP. COMP. TRANSITORIA-SEGUNDA', '185128'),
    (2432, 'SUB-2432', 'SBM5', 'LA UIF - PERÚ TIENE COMO UNA DE SUS FUNCIONES Y FACULTADES:.', 'SOLICITAR INFORMES, DOCUMENTOS, ANTECEDENTES Y TODO OTRO ELEMENTO QUE ESTIME ÚTIL PARA EL CUMPLIMIENTO DE SUS FUNCIONES.', 'DISP. COMP.MOD. - PRIMERA', '185129'),
    (2433, 'SUB-2433', 'SBM5', 'SOLICITAR INFORMES, DOCUMENTOS, ANTECEDENTES Y TODO OTRO ELEMENTO QUE ESTIME ÚTIL PARA EL CUMPLIMIENTO DE SUS FUNCIONES, A CUALQUIER ORGANISMO PÚBLICO DEL GOBIERNO NACIONAL, A LOS GOBIERNOS REGIONALES Y LOCALES, INSTITUCIONES Y EMPRESAS PERTENECIENTES A ÉSTOS, Y EN GENERAL A TODA INSTITUCIÓN Y EMPRESAS DEL ESTADO SIN EXCEPCIÓN NI RESERVA ALGUNA, EN EL MARCO DE LO ESTABLECIDO EN LA CONSTITUCIÓN POLÍTICA DEL PERÚ; ES UNA DE LAS FUNCIONES Y FACULTADES DE:.', 'LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185130'),
    (2434, 'SUB-2434', 'SBM5', 'SON FUNCIONES Y FACULTADES DE LA UIF INSCRIBIR A LOS SUJETOS OBLIGADOS Y A LOS OFICIALES DE CUMPLIMIENTO QUE ESTOS DESIGNEN, SIEMPRE QUE SATISFAGAN LOS REQUISITOS ESTABLECIDOS EN:.', 'LA PRESENTE LEY.', 'DISP. COMP.MOD. - PRIMERA', '185131'),
    (2435, 'SUB-2435', 'SBM5', 'SOLICITAR, RECIBIR, REQUERIR AMPLIACIONES Y ANALIZAR INFORMACIÓN SOBRE LAS OPERACIONES SOSPECHOSAS QUE LE REPORTEN LOS SUJETOS OBLIGADOS A INFORMAR POR LA LEY 29038 Y SUS ORGANISMOS SUPERVISORES, O LAS QUE DETECTE DE LA INFORMACIÓN CONTENIDA EN LAS BASES DE DATOS A LAS QUE TIENE ACCESO; ES UNA DE LAS FUNCIONES Y FACULTADES QUE TIENE LA:.', 'UIF-PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185132'),
    (2436, 'SUB-2436', 'SBM5', 'SOLICITAR, RECIBIR, REQUERIR AMPLIACIONES Y ANALIZAR INFORMACIÓN SOBRE LAS OPERACIONES SOSPECHOSAS QUE LE REPORTEN LOS SUJETOS OBLIGADOS A INFORMAR POR LA LEY 29038 Y SUS ORGANISMOS SUPERVISORES, O LAS QUE DETECTE DE LA INFORMACIÓN CONTENIDA EN LAS BASES DE DATOS A LAS QUE TIENE ACCESO; CORRESPONDE A UNA DE LAS:.', 'FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185133'),
    (2437, 'SUB-2437', 'SBM5', 'LA UIF - PERÚ TIENE COMO UNA DE SUS FUNCIONES Y FACULTADES:. DL 1106 - Lucha contra el lavado de activos', 'RECIBIR Y ANALIZAR LOS REGISTROS DE OPERACIONES A QUE HACE REFERENCIA EL ARTÍCULO 9 O CUALQUIER INFORMACIÓN RELACIONADA A ESTOS, LOS CUALES DEBERÁN SER ENTREGADOS OBLIGATORIAMENTE POR LOS SUJETOS OBLIGADOS A LA UIF - PERÚ POR EL MEDIO ELECTRÓNICO, PERIODICIDAD Y MODALIDAD QUE ÉSTA ESTABLEZCA', 'DISP. COMP.MOD. - PRIMERA', '185134'),
    (2438, 'SUB-2438', 'SBM5', 'RECIBIR Y ANALIZAR LOS REGISTROS DE OPERACIONES A QUE HACE REFERENCIA EL ARTÍCULO 9 O CUALQUIER INFORMACIÓN RELACIONADA A ESTOS, LOS CUALES DEBERÁN SER ENTREGADOS OBLIGATORIAMENTE POR LOS SUJETOS OBLIGADOS A LA UIF - PERÚ POR EL MEDIO ELECTRÓNICO, PERIODICIDAD Y MODALIDAD QUE ÉSTA ESTABLEZCA; ES UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185135'),
    (2439, 'SUB-2439', 'SBM5', 'LA UIF - PERÚ TIENE COMO UNA DE SUS FUNCIONES Y FACULTADES:.', 'COMUNICAR AL MINISTERIO PÚBLICO AQUELLAS OPERACIONES QUE LUEGO DEL ANÁLISIS E INVESTIGACIÓN RESPECTIVOS, SE PRESUMA QUE ESTÉN VINCULADAS A ACTIVIDADES DE LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DEL TERRORISMO, PARA QUE PROCEDA DE ACUERDO A LEY.', 'DISP. COMP.MOD. - PRIMERA', '185136'),
    (2440, 'SUB-2440', 'SBM5', 'COOPERAR EN EL ÁMBITO DE SU COMPETENCIA CON INVESTIGACIONES INTERNACIONALES Y/O SOLICITAR, RECIBIR, ANALIZAR Y COMPARTIR INFORMACIÓN, A SOLICITUD DE AUTORIDADES COMPETENTES DE OTROS PAÍSES QUE EJERZAN COMPETENCIAS ANÁLOGAS; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185137'),
    (2441, 'SUB-2441', 'SBM5', 'PARTICIPAR EN EL ÁMBITO DE SU COMPETENCIA EN INVESTIGACIONES CONJUNTAS CON OTRAS INSTITUCIONES PÚBLICAS NACIONALES, ENCARGADAS DE DETECTAR, INVESTIGAR Y DENUNCIAR LA COMISIÓN DE ILÍCITOS PENALES QUE TIENEN LA CARACTERÍSTICA DE DELITO PRECEDENTE DEL DELITO DE LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DE TERRORISMO; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185138'),
    (2442, 'SUB-2442', 'SBM5', 'PRESTAR LA ASISTENCIA TÉCNICA QUE LES SEA REQUERIDA, CUANDO SE TRATE DE INVESTIGACIONES RELACIONADAS CON EL LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DEL TERRORISMO; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185139'),
    (2443, 'SUB-2443', 'SBM5', 'REGULAR, EN COORDINACIÓN CON LOS ORGANISMOS SUPERVISORES DE LOS SUJETOS OBLIGADOS, LOS LINEAMIENTOS GENERALES Y ESPECÍFICOS, REQUISITOS, PRECISIONES, SANCIONES Y DEMÁS ASPECTOS REFERIDOS A LOS SISTEMAS DE PREVENCIÓN DE LOS SUJETOS OBLIGADOS A REPORTAR Y LOS REPORTES DE OPERACIONES SOSPECHOSAS Y DE REGISTRO DE OPERACIONES; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185140'),
    (2444, 'SUB-2444', 'SBM5', 'SUPERVISAR Y SANCIONAR EN MATERIA DE PREVENCIÓN DEL DELITO DE LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DE TERRORISMO, A AQUELLOS SUJETOS OBLIGADOS QUE CARECEN DE ORGANISMO SUPERVISOR; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185141'),
    (2445, 'SUB-2445', 'SBM5', 'EXCEPCIONALMENTE, DADA LA URGENCIA DE LAS CIRCUNSTANCIAS O EL PELIGRO EN LA DEMORA, Y SIEMPRE QUE SEA NECESARIO POR LA DIMENSIÓN Y NATURALEZA DE LA INVESTIGACIÓN, PODRÁ DISPONER EL CONGELAMIENTO DE FONDOS EN LOS CASOS VINCULADOS AL DELITO DE LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DEL TERRORISMO; CORRESPONDE A UNA:.', 'DE LAS FUNCIONES Y FACULTADES DE LA UIF - PERÚ.', 'DISP. COMP.MOD. - PRIMERA', '185142'),
    (2446, 'SUB-2446', 'SBM5', 'ESTABLÉZCASE LA OBLIGACIÓN PARA TODA PERSONA, NACIONAL O EXTRANJERA, QUE INGRESE O SALGA DEL PAÍS, DE DECLARAR BAJO JURAMENTO INSTRUMENTOS FINANCIEROS NEGOCIABLES EMITIDOS;AL PORTADOR; O DINERO EN EFECTIVO QUE PORTE CONSIGO POR SUMAS SUPERIORES A:.', 'US$ 10,000.00 (DIEZ MIL Y 00/100 DÓLARES DE LOS ESTADOS UNIDOS DE AMÉRICA), O SU EQUIVALENTE EN MONEDA NACIONAL U OTRA EXTRANJERA.', 'DISP. COMP.MOD. - CUARTA', '185145'),
    (2447, 'SUB-2447', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'COMPRAVENTA DE TÍTULOS VALORES - PÚBLICOS O PRIVADOS - O DE CUOTA PARTES DE FONDOS COMUNES DE INVERSIÓN.', 'DISP. COMP.MOD. - PRIMERA', '185147'),
    (2448, 'SUB-2448', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'COMPRAVENTA DE METALES Y/O PIEDRAS PRECIOSAS, SEGÚN RELACIÓN QUE SE ESTABLEZCA EN EL REGLAMENTO.', 'DISP. COMP.MOD. - PRIMERA', '185148'),
    (2449, 'SUB-2449', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'PAGO DE IMPORTACIONES.', 'DISP. COMP.MOD. - PRIMERA', '185150'),
    (2450, 'SUB-2450', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'COBRO DE EXPORTACIONES.', 'DISP. COMP.MOD. - PRIMERA', '185151'),
    (2451, 'SUB-2451', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'VENTA DE CARTERA DE LA ENTIDAD FINANCIERA A TERCEROS.', 'DISP. COMP.MOD. - PRIMERA', '185152'),
    (2452, 'SUB-2452', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'CANCELACIONES ANTICIPADAS DE PRÉSTAMOS.', 'DISP. COMP.MOD. - PRIMERA', '185154'),
    (2453, 'SUB-2453', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'CONSTITUCIÓN DE FIDEICOMISOS Y TODO TIPO DE OTROS ENCARGOS FIDUCIARIOS Y DE COMISIONES DE CONFIANZA.', 'DISP. COMP.MOD. - PRIMERA', '185155'),
    (2454, 'SUB-2454', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'COMPRA VENTA DE BIENES Y SERVICIOS.', 'DISP. COMP.MOD. - PRIMERA', '185156'),
    (2455, 'SUB-2455', 'SBM5', 'UNO DE LOS CONCEPTOS A REGISTRAR POR PARTE DE LOS SUJETOS OBLIGADOS A INFORMAR CADA OPERACIÓN QUE REALICE O QUE SE HAYA INTENTADO REALIZAR QUE IGUALE O SUPERE EL MONTO QUE ESTABLEZCA LA UIF - PERÚ ES:.', 'OPERACIONES A FUTURO PACTADAS CON LOS CLIENTES.', 'DISP. COMP.MOD. - PRIMERA', '185157'),
    (2456, 'SUB-2456', 'SBM5', 'EL REGISTRO DE OPERACIONES DEBE SER LLEVADO EN FORMA PRECISA Y COMPLETA POR LOS SUJETOS OBLIGADOS, EN EL DÍA EN QUE HAYA OCURRIDO LA OPERACIÓN Y SE CONSERVARÁ DURANTE:.', 'DIEZ (10) AÑOS A PARTIR DE LA FECHA DE LA MISMA, UTILIZANDO PARA TAL FIN MEDIOS INFORMÁTICOS, MICROFILMACIÓN O MEDIOS SIMILARES.', 'DISP. COMP.MOD. - PRIMERA', '185158'),
    (2457, 'SUB-2457', 'SBM5', 'REGISTRO DE OPERACIONES.- LA OBLIGACIÓN DE REGISTRAR LAS OPERACIONES NO SERÁ DE APLICACIÓN CUANDO SE TRATE DE:.', 'CLIENTES HABITUALES.', 'DISP. COMP.MOD. - PRIMERA', '185159'),
    (2458, 'SUB-2458', 'SBM5', 'LAS OPERACIONES MÚLTIPLES QUE EN CONJUNTO IGUALEN O SUPEREN DETERMINADO MONTO FIJADO POR LA UIF - PERÚ, SERÁN CONSIDERADAS COMO:.', 'UNA SOLA OPERACIÓN SI SON REALIZADAS POR O EN BENEFICIO DE DETERMINADA PERSONA.', 'DISP. COMP.MOD. - PRIMERA', '185160'),
    (2459, 'SUB-2459', 'SBM5', 'CUMPLIR CON TODAS LAS NORMAS PERTINENTES EN MATERIA DE PREVENCIÓN DEL LAVADO DE ACTIVOS Y DEL FINANCIAMIENTO DEL TERRORISMO, CONFORME A LA LEGISLACIÓN DE LA MATERIA.- CORRESPONDE A:.', 'OBLIGACIONES DEL NOTARIO.', 'DISP. COMP.MOD. - SEXTA', '185161'),
    (2460, 'SUB-2460', 'SBM5', 'ES OBLIGACIÓN DEL NOTARIO ACCEDER A LA BASE DE DATOS DEL RENIEC EN AQUELLOS LUGARES DONDE SE CUENTE CON ACCESO A INTERNET Y SEA POSIBLE PARA LA INDICADA ENTIDAD BRINDAR EL SERVICIO DE CONSULTAS EN LÍNEA PARA LA VERIFICACIÓN DE:. DL 1106 - Lucha contra el lavado de activos', 'LA IDENTIDAD DE LOS INTERVINIENTES MEDIANTE LA VERIFICACIÓN DE LAS IMÁGENES, DATOS Y/O LA IDENTIFICACIÓN POR COMPARACIÓN BIOMÉTRICA.', 'DISP. COMP.MOD. - SEPTIMA', '185162'),
    (2461, 'SUB-2461', 'SBM5', 'ES LA ACCIÓN O CONDUCTA, QUE CAUSA DAÑO A LA INTEGRIDAD CORPORAL O A LA SALUD. SE INCLUYE EL MALTRATO POR NEGLIGENCIA, DESCUIDO O POR PRIVACIÓN DE LAS NECESIDADES BÁSICAS, QUE HAYAN OCASIONADO DAÑO FÍSICO O QUE PUEDAN LLEGAR A OCASIONARLO, SIN IMPORTAR EL TIEMPO QUE SE REQUIERA PARA SU RECUPERACIÓN, ES UN TIPO DE:.', 'VIOLENCIA FÍSICA.', 'ART. 8', '185163'),
    (2462, 'SUB-2462', 'SBM5', 'ES LA ACCIÓN U OMISIÓN, TENDIENTE A CONTROLAR O AISLAR A LA PERSONA CONTRA SU VOLUNTAD, A HUMILLARLA, AVERGONZARLA, INSULTARLA, ESTIGMATIZARLA O ESTEREOTIPARLA, SIN IMPORTAR EL TIEMPO QUE SE REQUIERA PARA SU RECUPERACIÓN, ES UN TIPO DE:.', 'VIOLENCIA PSICOLÓGICA.', 'ART. 8', '185164'),
    (2463, 'SUB-2463', 'SBM5', 'EN LA ACTUACIÓN DE LOS OPERADORES DE JUSTICIA, ORIGINADA POR HECHOS QUE CONSTITUYEN ACTOS DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR, SE EVITA LA:.', 'DOBLE VICTIMIZACIÓN DE LAS PERSONAS AGRAVIADAS.', 'ART. 18', '185165'),
    (2464, 'SUB-2464', 'SBM5', 'LA DENUNCIA POR ACTOS DE VIOLENCIA CONTRA LAS MUJERES TAMBIÉN PUEDE INTERPONERLA:.', 'LA DEFENSORÍA DEL PUEBLO.', 'ART. 15', '185166'),
    (2465, 'SUB-2465', 'SBM5', 'A LA JUSTIFICACIÓN DE LAS INASISTENCIAS Y TARDANZAS AL CENTRO DE TRABAJO DERIVADAS DE DICHOS ACTOS DE VIOLENCIA, CONSTITUYE:.', 'DERECHOS LABORALES.', 'ART. 11', '185167'),
    (2466, 'SUB-2466', 'SBM5', 'LAS DISPOSICIONES DE LA LEY 30364 SE APLICAN A TODOS LOS TIPOS DE VIOLENCIA CONTRA LAS MUJERES POR SU CONDICIÓN DE TALES Y CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR, CONSTITUYE EL:.', 'EL ÁMBITO.', 'ART. 4', '185168'),
    (2467, 'SUB-2467', 'SBM5', 'A QUE PRINCIPIO CONSTITUYE EL SIGUIENTE ANUNCIADO: "EN TODAS LAS MEDIDAS CONCERNIENTES A LAS NIÑAS Y NIÑOS ADOPTADAS POR INSTITUCIONES PÚBLICAS O PRIVADAS DE BIENESTAR SOCIAL, LOS TRIBUNALES, LAS AUTORIDADES ADMINISTRATIVAS O LOS ÓRGANOS LEGISLATIVOS SE DEBE TENER EN CONSIDERACIÓN PRIMORDIAL EL INTERÉS SUPERIOR DEL NIÑO":', 'PRINCIPIO DE INTERÉS SUPERIOR DEL NIÑO.', 'ART. 2', '185169'),
    (2468, 'SUB-2468', 'SBM5', 'A QUE PRINCIPIO CONSTITUYE EL SIGUIENTE ENUNCIADO: "TODOS LOS PROCESOS POR VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR SE DESARROLLAN CONSIDERANDO EL MÍNIMO DE FORMALISMO, EN ESPACIOS AMIGABLES PARA LAS PRESUNTAS VÍCTIMAS, FAVORECIENDO QUE ESTAS CONFÍEN EN EL SISTEMA Y COLABOREN CON ÉL PARA UNA ADECUADA SANCIÓN AL AGRESOR Y LA RESTITUCIÓN DE SUS DERECHOS VULNERADOS":', 'PRINCIPIO DE SENCILLEZ Y ORALIDAD.', 'ART. 2', '185170'),
    (2469, 'SUB-2469', 'SBM5', 'A QUÉ TIPO DE ENFOQUE SE REFIERE EL SIGUIENTE ANUNCIADO: "RECONOCE LA EXISTENCIA DE CIRCUNSTANCIAS ASIMÉTRICAS EN LA RELACIÓN ENTRE HOMBRES Y MUJERES, CONTRIBUIDAS SOBRE LA BASE DE LAS DIFERENCIAS DE GÉNERO QUE SE CONSTITUYEN EN UNA DE LAS CAUSAS PRINCIPALES DE LA VIOLENCIA HACIA LAS MUJERES. ESTE ENFOQUE DEBE ORIENTAR EL DISEÑO DE LAS ESTRATEGIAS DE INTERVENCIÓN ORIENTADAS AL LOGRO DE LAS IGUALDAD DE OPORTUNIDADES ENTRE HOMBRES Y MUJERES":', 'ENFOQUE DE GÉNERO.', 'ART. 3', '185171'),
    (2470, 'SUB-2470', 'SBM5', 'A QUE ENFOQUE CORRESPONDE EL SIGUIENTE ANUNCIADO: "RECONOCE QUE EL OBJETIVO PRINCIPAL DE TODA INTERVENCIÓN EN EL MARCO DE LA LEY DEBE SER LA REALIZACIÓN DE LOS DERECHOS HUMANOS, IDENTIFICANDO A LOS TITULARES DE DERECHOS Y AQUELLO A LO QUE TIENEN DERECHO CONFORME A SUS PARTICULARES NECESIDADES; IDENTIFICANDO, ASIMISMO, A LOS OBLIGADOS O TITULARES DE DEBERES Y DE LAS OBLIGACIONES QUE LES CORRESPONDEN. SE PROCURA FORTALECER LA CAPACIDAD DE LOS TITULARES DE DERECHOS PARA REIVINDICAR ESTOS Y DE LOS TITULARES DE DEBERES PARA CUMPLIR SUS OBLIGACIONES":', 'ENFOQUE DE DERECHOS HUMANOS', 'ART. 3', '185172'),
    (2471, 'SUB-2471', 'SBM5', 'A QUE ENFOQUE CORRESPONDE EL SIGUIENTE ANUNCIADO: "RECONOCE QUE LA EXPERIENCIA QUE LAS MUJERES TIENEN DE LA VIOLENCIA SE VE INFLUIDA POR FACTORES E IDENTIDADES COMO SU ETNIA, COLOR, RELIGIÓN; OPINIÓN POLÍTICA O DE OTRO TIPO; ORIGEN NACIONAL O SOCIAL, PATRIMONIO; ESTADO CIVIL, ORIENTACIÓN SEXUAL, CONDICIÓN DE SEROPOSITIVA, CONDICIÓN DE INMIGRANTE O REFUGIADA, EDAD O DISCAPACIDAD; Y, EN SU CASO, INCLUYE MEDIDAS ORIENTADAS A DETERMINADOS GRUPO DE MUJERES":', 'ENFOQUE DE INTERSECCIONALIDAD.', 'ART. 3', '185173'),
    (2472, 'SUB-2472', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ U OTRAS ENTIDADES ENCARGADAS DE EJECUTAR LA MEDIDA DE PROTECCIÓN REMITEN AL JUZGADO DE FAMILIA UN INFORME SOBRE LA EJECUCIÓN DE LA MEDIDA, DENTRO DE LOS:', 'QUINCE (15) DÍAS CONTADOS DESDE LA FECHA EN QUE FUE NOTIFICADA.', 'ART. 23 C', '185174'),
    (2473, 'SUB-2473', 'SBM5', 'INFORME DE CUMPLIMIENTO DE LA MEDIDA DE PROTECCIÓN: EN CASOS DE RIESGO SEVERO, DICHO INFORME DEBE SER REMITIDO DENTRO DE LOS:', 'CINCO (5) DÍAS CONTADOS DESDE LA FECHA EN QUE FUE NOTIFICADA LA MEDIDA DE PROTECCIÓN.', 'ART. 23 C', '185175'),
    (2474, 'SUB-2474', 'SBM5', 'EL QUE DESOBEDECE, INCUMPLE O RESISTE UNA MEDIDA DE PROTECCIÓN DICTADA EN UN PROCESO ORIGINADO POR HECHOS QUE CONFIGURAN ACTOS DE VIOLENCIA CONTRA LAS MUJERES O CONTRA INTEGRANTES DEL GRUPO FAMILIAR, COMETE DELITO DE:', 'RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD PREVISTO EN EL CÓDIGO PENAL.', 'ART. 24', '185176'),
    (2475, 'SUB-2475', 'SBM5', 'LA PRESENTE LEY TIENE POR OBJETO PREVENIR, ERRADICAR Y SANCIONAR TODA FORMA DE VIOLENCIA PRODUCIDA EN EL ÁMBITO:.', 'PÚBLICO O PRIVADO.', 'ART. 1', '185177'),
    (2476, 'SUB-2476', 'SBM5', 'TIENE POR OBJETO PREVENIR, ERRADICAR Y SANCIONAR TODA FORMA DE VIOLENCIA CONTRA LAS MUJERES POR SU CONDICIÓN DE TALES; EN ESPECIAL, CUANDO SE ENCUENTRAN EN SITUACIÓN DE VULNERABILIDAD, POR LA EDAD O SITUACION FÍSICA COMO LAS NIÑAS, NIÑOS, ADOLESCENTES, PERSONAS ADULTAS MAYORES Y CON....... :', 'DISCAPACIDAD', 'ART. 1', '185178'),
    (2477, 'SUB-2477', 'SBM5', '¿A QUÉ PRINCIPIO RECTOR HACE REFERENCIA EL SIGUIENTE TEXTO: "SE GARANTIZA LA IGUALDAD ENTRE MUJERES Y HOMBRES. PROHÍBESE TODA FORMA DE DISCRIMINACIÓN".', 'PRINCIPIO DE IGUALDAD Y NO DISCRIMINACIÓN.', 'ART. 2', '185179'),
    (2478, 'SUB-2478', 'SBM5', 'EN EL PRINCIPIO DEL INTERES SUPERIOR DEL NIÑO: LAS MEDIDAS ADOPTADAS POR INSTITUCIONES PÚBLICAS O PRIVADAS DE BIENESTAR SOCIAL, LOS TRIBUNALES, LAS AUTORIDADES ADMINISTRATIVAS O LOS ÓRGANOS LEGISLATIVOS DEBEN TENER EN CONSIDERACIÓN PRIMORDIAL EL INTERÉS SUPERIOR DEL........', 'DEL NIÑO.', 'ART. 2', '185180'),
    (2479, 'SUB-2479', 'SBM5', '¿A QUÉ PRINCIPIO RECTOR HACE REFERENCIA EL SIGUIENTE TEXTO: EL ESTADO ADOPTA SIN DILACIONES, TODAS LAS POLÍTICAS ORIENTADAS A PREVENIR, SANCIONAR Y ERRADICAR TODA FORMA DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR. IMPONIENDOSE LAS SANCIONES CORRESPONDIENTES.', 'PRINCIPIO DE LA DEBIDA DILIGENCIA.', 'ART. 2', '185181'),
    (2480, 'SUB-2480', 'SBM5', '¿A QUÉ PRINCIPIO RECTOR HACE REFERENCIA EL TEXTO: LOS OPERADORES DE JUSTICIA Y LA POLICÍA NACIONAL DEL PERÚ, ANTE UN HECHO O AMENAZA DE VIOLENCIA, DEBEN ACTUAR EN FORMA OPORTUNA, SIN DILACIÓN POR RAZONES PROCEDIMENTALES, FORMALES O DE OTRA NATURALEZA, DISPONIENDO EL EJERCICIO DE LAS MEDIDAS DE PROTECCIÓN PREVISTAS EN LA LEY Y OTRAS NORMAS, CON LA FINALIDAD DE ATENDER EFECTIVAMENTE A LA VÍCTIMA.', 'PRINCIPIO DE INTERVENCIÓN INMEDIATA Y OPORTUNA.', 'ART. 2', '185182'),
    (2481, 'SUB-2481', 'SBM5', '¿A QUÉ ENFOQUE HACE REFERENCIA EL TEXTO: RECONOCE QUE EN LA VIOLENCIA CONTRA LAS MUJERES CONFLUYEN MÚLTIPLES CAUSAS Y FACTORES QUE ESTÁN PRESENTES EN DISTINTOS ÁMBITOS, A NIVEL INDIVIDUAL, FAMILIAR, COMUNITARIO Y ESTRUCTURAL.', 'ENFOQUE DE INTEGRALIDAD.', 'ART. 3', '185183'),
    (2482, 'SUB-2482', 'SBM5', '¿A QUÉ ENFOQUE HACE REFERENCIA EL TEXTO?. NO ADMITE ACEPTAR PRÁCTICAS CULTURALES DISCRIMINATORIAS QUE TOLERAN LA VIOLENCIA U OBSTACULIZAN EL GOCE DE IGUALDAD DE DERECHOS ENTRE PERSONAS DE GÉNEROS DIFERENTES.', 'ENFOQUE DE INTERCULTURALIDAD.', 'ART. 3', '185184'),
    (2483, 'SUB-2483', 'SBM5', '¿QUÉ ENFOQUE HACE REFERENCIA EL TEXTO?. RECONOCE QUE ES NECESARIO IDENTIFICAR LAS RELACIONES DE PODER ENTRE DISTINTAS EDADES DE LA VIDA Y SUS VINCULACIONES PARA MEJORAR LAS CONDICIONES DE VIDA O EL DESARROLLO COMÚN.', 'ENFOQUE GENERACIONAL.', 'ART. 3', '185185'),
    (2484, 'SUB-2484', 'SBM5', 'LAS DISPOSICIONES DE LA PRESENTE LEY SE APLICAN A TODOS LOS TIPOS DE VIOLENCIA CONTRA LAS MUJERES POR SU CONDICIÓN DE TALES Y CONTRA LOS:.', 'INTEGRANTES DEL GRUPO FAMILIAR.', 'ART. 4', '185186'),
    (2485, 'SUB-2485', 'SBM5', 'DEFINICION DE VIOLENCIA CONTRA LAS MUJERES: ES CUALQUIER ACCIÓN O....:.', 'CONDUCTA QUE LES CAUSA MUERTE, DAÑO O SUFRIMIENTO FÍSICO, SEXUAL O PSICOLÓGICO POR SU CONDICIÓN DE TALES, TANTO EN EL ÁMBITO PÚBLICO COMO EN EL PRIVADO.', 'ART. 5', '185187'),
    (2486, 'SUB-2486', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES CUALQUIER ACCIÓN O CONDUCTA QUE LES CAUSA:.', 'MUERTE', 'ART. 5', '185188'),
    (2487, 'SUB-2487', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES CUALQUIER ACCIÓN O CONDUCTA QUE LES CAUSA MUERTE, DAÑO O SUFRIMIENTO FÍSICO, SEXUAL O:.', 'PSICOLÓGICO', 'ART. 5', '185189'),
    (2488, 'SUB-2488', 'SBM5', 'SE ENTIENDE POR VIOLENCIA CONTRA LAS MUJERES:.', 'LA QUE TENGA LUGAR DENTRO DE LA FAMILIA O UNIDAD DOMÉSTICA O EN CUALQUIER OTRA RELACION INTERPERSONAL.', 'ART. 5', '185190'),
    (2489, 'SUB-2489', 'SBM5', 'SE ENTIENDE POR VIOLENCIA CONTRA LAS MUJERES:.', 'LA QUE TENGA LUGAR DENTRO DE LA FAMILIA.', 'ART. 5', '185192'),
    (2490, 'SUB-2490', 'SBM5', '¿QUÉ PERSONAS PUEDEN COMETER VIOLENCIA CONTRA LAS MUJERES?.', 'CUALQUIER PERSONA.', 'ART. 5', '185193'),
    (2491, 'SUB-2491', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'EL ABUSO SEXUAL.', 'ART. 5', '185194'),
    (2492, 'SUB-2492', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'LA TORTURA.', 'ART. 5', '185195'),
    (2493, 'SUB-2493', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'LA TRATA DE PERSONAS.', 'ART. 5', '185196'),
    (2494, 'SUB-2494', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'LA PROSTITUCIÓN FORZADA.', 'ART. 5', '185197'),
    (2495, 'SUB-2495', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'EL ACOSO SEXUAL.', 'ART. 5', '185198'),
    (2496, 'SUB-2496', 'SBM5', 'EN LA VIOLENCIA CONTRA LAS MUJERES SE ENTIENDE LA QUÉ SEA PERPETRADA O TOLERADA POR LOS AGENTES:.', 'DEL ESTADO, DONDE QUIERA QUE OCURRA.', 'ART. 5', '185199'),
    (2497, 'SUB-2497', 'SBM5', 'SE ENTIENDE POR VIOLENCIA CONTRA LAS MUJERES: LA QUE SEA PERPETRADA O TOLERADA POR LOS AGENTES DEL ESTADO:.', 'DONDE QUIERA QUE OCURRA.', 'ART. 5', '185200'),
    (2498, 'SUB-2498', 'SBM5', 'LA VIOLENCIA CONTRA CUALQUIER INTEGRANTE DEL GRUPO FAMILIAR SE PRODUCE EN EL CONTEXTO DE UNA RELACIÓN DE:.', 'RESPONSABILIDAD', 'ART. 6', '185201'),
    (2499, 'SUB-2499', 'SBM5', 'LA VIOLENCIA CONTRA CUALQUIER INTEGRANTE DEL GRUPO FAMILIAR SE PRODUCE EN EL CONTEXTO DE UNA RELACIÓN DE:.', 'CONFIANZA', 'ART. 6', '185202'),
    (2500, 'SUB-2500', 'SBM5', '¿A QUIÉN SE DEBERÁ TENER ESPECIAL CONSIDERACIÓN EN LA VIOLENCIA CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR:', 'CON LOS ADULTOS MAYORES.', 'ART. 6', '185203')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

