INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2501 a 2600
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2501, 'SUB-2501', 'SBM5', 'CON QUIÉN SE DEBERÁ TENER ESPECIAL CONSIDERACIÓN EN LA VIOLENCIA CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR ANTE CUALQUIE ACCION QUE LE CAUSE DAÑO, ETC:', 'CON LOS ADOLESCENTES.', 'ART. 6', '185204'),
    (2502, 'SUB-2502', 'SBM5', 'EN LA VIOLENCIA CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR CON QUIEN SE DEBERÁ TENER ESPECIAL CONSIDERACIÓN :', 'CON LAS PERSONAS CON DISCAPACIDAD.', 'ART. 6', '185205'),
    (2503, 'SUB-2503', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LAS MUJERES DURANTE TODO SU CICLO DE VIDA, QUE COMPRENDE DESDE:.', 'NIÑA, ADOLESCENTES, JOVEN, ADULTA Y ADULTA MAYOR.', 'ART. 7', '185206'),
    (2504, 'SUB-2504', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A LOS:.', 'CÓNYUGES', 'ART. 7', '185207'),
    (2505, 'SUB-2505', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'EXCÓNYUGES', 'ART. 7', '185208'),
    (2506, 'SUB-2506', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'CONVIVIENTES', 'ART. 7', '185209'),
    (2507, 'SUB-2507', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'EXCONVIVIENTES', 'ART. 7', '185210'),
    (2508, 'SUB-2508', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'MADRASTRAS', 'ART. 7', '185211'),
    (2509, 'SUB-2509', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'ASCENDIENTES Y DESCENDIENTES POR CONSANGUINIDAD, ADOPCIÓN O POR AFINIDAD.', 'ART. 7', '185212'),
    (2510, 'SUB-2510', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'LOS PARIENTES COLATERALES HASTA EL CUARTO GRADO DE CONSANGUINIDAD Y SEGUNDO DE AFINIDAD.', 'ART. 7', '185214'),
    (2511, 'SUB-2511', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A LOS QUE:', 'HABITAN EN EL MISMO HOGAR, SIEMPRE QUE NO MEDIEN RELACIONES CONTRACTUALES O LABORALES AL MOMENTO DE PRODUCIRSE LA VIOLENCIA.', 'ART. 7', '185215'),
    (2512, 'SUB-2512', 'SBM5', '¿CUÁLES SON LOS TIPOS DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR?.', 'FÍSICA, PSICOLÓGICA, SEXUAL Y ECONÓMICA O PATRIMONIAL.', 'ART. 8', '185216'),
    (2513, 'SUB-2513', 'SBM5', 'EN LA VIOLENCIA SEXUAL SE CONSIDERAN TALES LA EXPOSICIÓN A MATERIAL PORNOGRÁFICO Y QUE VULNERAN EL DERECHO DE LAS PERSONAS A DECIDIR VOLUNTARIAMENTE ACERCA DE SU VIDA SEXUAL O REPRODUCTIVA, A TRAVÉS DE AMENAZAS, COERCION, Y USO DE LA FUERZA O ...........', 'INTIMIDACIÓN', 'ART. 8', '185217'),
    (2514, 'SUB-2514', 'SBM5', 'LA VIOLENCIA ECONÓMICA O PATRIMONIAL ES LA ACCIÓN U OMISIÓN QUE OCASIONA UN MENOSCABO EN LOS RECURSOS ECONÓMICOS O PATRIMONIALES DE LAS MUJERES POR SU CONDICIÓN DE TALES O CONTRA CUALQUIER INTEGRANTE DEL GRUPO FAMILIAR, EN EL MARCO DE RELACIONES DE PODER, RESPONSABILIDAD O CONFIANZA, POR EJEMPLO, A TRAVÉS DE LA PERTURBACIÓN DE LA POSESIÓN:', 'TENENCIA O PROPIEDAD DE SUS BIENES.', 'ART. 8', '185218'),
    (2515, 'SUB-2515', 'SBM5', 'LA VIOLENCIA ECONÓMICA O PATRIMONIAL ES LA ACCIÓN U OMISIÓN QUE OCASIONA UN MENOSCABO EN LOS RECURSOS ECONÓMICOS O PATRIMONIALES DE LAS MUJERES POR SU CONDICIÓN DE TALES O CONTRA CUALQUIER INTEGRANTE DEL GRUPO FAMILIAR, EN EL MARCO DE RELACIONES DE PODER, RESPONSABILIDAD O CONFIANZA, POR EJEMPLO, A TRAVÉS DE LA LIMITACIÓN O CONTROL DE SUS:', 'INGRESOS', 'ART. 8', '185219'),
    (2516, 'SUB-2516', 'SBM5', 'SON COMPETENTES PARA CONOCER LAS DENUNCIAS POR ACTOS DE VIOLENCIA CONTRA LAS MUJERES O CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR:.', 'JUZGADOS DE FAMILIA.', 'ART. 14', '185220'),
    (2517, 'SUB-2517', 'SBM5', 'CUANDO SE TRATA DE UNA DENUNCIA VERBAL, SE LEVANTA ACTA SIN OTRA EXIGENCIA QUE LA DE:.', 'SUMINISTRAR UNA SUCINTA RELACIÓN DE LOS HECHOS.', 'ART. 15', '185221'),
    (2518, 'SUB-2518', 'SBM5', 'LA DENUNCIA PUEDE SER INTERPUESTA POR LA PERSONA PERJUDICADA O POR CUALQUIER OTRA EN SU FAVOR, SIN NECESIDAD DE TENER SU:.', 'REPRESENTACIÓN', 'ART. 15', '185222'),
    (2519, 'SUB-2519', 'SBM5', '¿CUÁLES SON LAS MEDIDAS DE PROTECCIÓN QUE PUEDEN DICTARSE EN LOS PROCESOS POR ACTOS DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR?.', 'IMPEDIMENTO DE ACERCAMIENTO O PROXIMIDAD A LA VÍCTIMA EN CUALQUIER FORMA.', 'ART. 22', '185223'),
    (2520, 'SUB-2520', 'SBM5', 'TIENE COMO OBJETIVO CONTRIBUIR A LA INTERVENCIÓN ARTICULADA Y MULTIDISCIPLINARIA A TRAVÉS DE UN SISTEMA INTEGRAL CONTINUO DE ESPECIALIZACIÓN Y PERFECCIONAMIENTO DE LOS OPERADORES EN EL ROL QUE LE COMPETE EN LA LUCHA INTEGRAL CONTRA LA VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR, PARA UNA ATENCIÓN OPORTUNA Y EFECTIVA, INCLUYENDO LA EVALUACIÓN DE SU IMPACTO:.', 'EL CENTRO DE ALTOS ESTUDIOS CONTRA LA VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR, BAJO LA DIRECCIÓN DEL MINISTERIO DE LA MUJER Y POBLACIONES VULNERABLES.', 'ART. 44 Ley N° 30364 - Ley para Prevenir, Sancionar y Erradicar la Violencia contra las Mujeres', '185224'),
    (2521, 'SUB-2521', 'SBM5', 'PROHIBICIÓN DE COMUNICACIÓN CONTRA LA VÍCTIMA VÍA EPISTOLAR, TELEFÓNICA, ELECTRÓNICA; ASIMISMO, VÍA CHAT, REDES SOCIALES, RED INSTITUCIONAL, INTRANET U OTRAS REDES O FORMAS DE COMUNICACIÓN, CONSTITUYE:.', 'OBJETO Y TIPOS DE MEDIDAS DE PROTECCIÓN.', 'ART. 22', '185225'),
    (2522, 'SUB-2522', 'SBM5', 'ES RESPONSABLE DE EJECUTAR LAS MEDIDAS DE PROTECCIÓN DICTADAS, PARA LO CUAL DEBE TENER UN MAPA GRÁFICO Y GEORREFERENCIAL DE REGISTRO DE TODAS LAS VÍCTIMAS CON LAS MEDIDAS DE PROTECCIÓN QUE LES HAYAN SIDO NOTIFICADAS:.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 23 A', '185226'),
    (2523, 'SUB-2523', 'SBM5', 'EL QUE DESOBEDECE, INCUMPLE O RESISTE A UNA MEDIDA DE PROTECCIÓN DICTADA EN UN PROCESO ORIGINADO POR HECHOS QUE CONFIGURAN ACTOS DE VIOLENCIA CONTRA LAS MUJERES O CONTRA INTEGRANTES DEL GRUPO FAMILIAR, COMETE DELITO DE RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD PREVISTO EN EL:.', 'CÓDIGO PENAL.', 'ART. 24', '185227'),
    (2524, 'SUB-2524', 'SBM5', 'LOS CERTIFICADOS E INFORMES QUE EXPIDAN LOS MÉDICOS DE LOS ESTABLECIMIENTOS PÚBLICOS DE SALUD DE LOS DIFERENTES SECTORES E INSTITUCIONES DEL ESTADO Y NIVELES DE GOBIERNO, TIENEN:.', 'VALOR PROBATORIO ACERCA DEL ESTADO DE SALUD FÍSICA Y MENTAL.', 'ART. 26', '185228'),
    (2525, 'SUB-2525', 'SBM5', 'ES OBLIGACIÓN IMPLEMENTAR, EN COORDINACIÓN CON EL MINISTERIO DE LA MUJER Y POBLACIONES VULNERABLES, SERVICIOS DE ATENCIÓN E INTERVENCIÓN PARA VARONES Y PERSONAS AGRESORAS:.', 'LOS GOBIERNOS LOCALES.', 'ART. 32', '185229'),
    (2526, 'SUB-2526', 'SBM5', 'EN LOS PROCESOS POR DELITOS VINCULADOS A ACTOS DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR, LOS JUZGADOS PENALES DEBEN PRONUNCIARSE EN LA SENTENCIA CONDENATORIA ACERCA DEL TRATAMIENTO ESPECIALIZADO PARA EL AGRESOR QUE NO CUMPLA PENA:.', 'PRIVATIVA DE LIBERTAD EFECTIVA', 'ART. 32', '185230'),
    (2527, 'SUB-2527', 'SBM5', 'IMPEDIMENTO DE ACERCAMIENTO O PROXIMIDAD A LA VÍCTIMA EN CUALQUIER FORMA, A SU DOMICILIO, CENTRO DE TRABAJO, CENTRO DE ESTUDIOS, LUGAR DE ESPARCIMIENTO U OTROS DONDE AQUELLA REALICE SUS ACTIVIDADES COTIDIANAS DE HABITUAL CONCURRENCIA, A UNA DISTANCIA IDÓNEA, DETERMINADA POR LA AUTORIDAD JUDICIAL, PARA GARANTIZAR SU SEGURIDAD E INTEGRIDAD, CONSTITUYE UNA:.', 'MEDIDA DE PROTECCIÓN.', 'ART. 22', '185231'),
    (2528, 'SUB-2528', 'SBM5', 'EL RETIRO DEL AGRESOR DEL DOMICILIO EN EL QUE SE ENCUENTRA LA VICTIMA, CONSTITUYE UNA:.', 'MEDIDA DE PROTECCIÓN.', 'ART. 22', '185232'),
    (2529, 'SUB-2529', 'SBM5', 'EN LOS PROCESOS ORIGINADOS POR HECHOS QUE CONSTITUYEN ACTOS DE VIOLENCIA CONTRA LAS MUJERES O CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR COMETE DELITO SANCIONADO EN LOS QUE:', 'REHÚSA O RETARDA ALGÚN ACTO A SU CARGO.', 'ART. 21', '185233'),
    (2530, 'SUB-2530', 'SBM5', 'CUANDO LA VÍCTIMA SEA NIÑA, NIÑO, ADOLESCENTE O MUJER, SU DECLARACIÓN DEBE PRACTICARSE BAJO LA TÉCNICA DE ENTREVISTA:.', 'ÚNICA', 'ART. 19', '185234'),
    (2531, 'SUB-2531', 'SBM5', 'LA SENTENCIA QUE PONGA FIN AL PROCESO POR DELITOS VINCULADOS A HECHOS QUE CONSTITUYEN ACTOS DE VIOLENCIA CONTRA LA MUJER Y LOS INTEGRANTES DEL GRUPO FAMILIAR PUEDE SER:.', 'ABSOLUTORIA O CONDENATORIA.', 'ART. 20', '185235'),
    (2532, 'SUB-2532', 'SBM5', 'SON COMPETENTES PARA CONOCER LAS DENUNCIAS POR ACTOS DE VIOLENCIA CONTRA LAS MUJERES O CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR, LOS:.', 'JUZGADOS DE FAMILIA.', 'ART. 14', '185236'),
    (2533, 'SUB-2533', 'SBM5', 'LAS DENUNCIAS POR ACTOS DE VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR SE REGULAN POR LAS NORMAS PREVISTAS EN LA PRESENTE LEY 30364 Y, DE MANERA SUPLETORIA, POR EL:.', 'CÓDIGO PROCESAL PENAL.', 'ART. 13', '185237'),
    (2534, 'SUB-2534', 'SBM5', 'EL JUEZ A CARGO DEL PROCESO PUEDE, A PEDIDO DE LA VÍCTIMA Y ATENDIENDO A LA GRAVEDAD DE LA SITUACIÓN, CONCEDER HASTA UN MÁXIMO DE 5 MESES CONSECUTIVOS DE SUSPENSIÓN DE LA RELACIÓN LABORAL SIN GOCE DE REMUNERACIONES, CONSTITUYE UN:.', 'DERECHO LABORAL.', 'ART. 11', '185238'),
    (2535, 'SUB-2535', 'SBM5', 'EL FISCAL O JUEZ A CARGO DE CUALQUIER PROCESO DE VIOLENCIA, DEBE PONDERAR LA PROPORCIONALIDAD ENTRE LA EVENTUAL AFECTACIÓN CAUSADA Y LAS MEDIDAS DE PROTECCIÓN Y DE REHABILITACIÓN A ADOPTARSE. PARA ELLO, DEBE HACER UN JUICIO DE RAZONABILIDAD DE ACUERDO CON LAS CIRCUNSTANCIAS DEL CASO, EMITIENDO DECISIONES QUE PERMITAN PROTEGER EFECTIVAMENTE LA VIDA, LA SALUD Y LA INTEGRIDAD DE LAS VÍCTIMAS. LA ADOPCIÓN DE ESTAS MEDIDAS SE ADECÚA A LAS FASES DEL CICLO DE LA VIOLENCIA Y A LAS DIVERSAS TIPOLOGÍAS QUE PRESENTA LA VIOLENCIA CONTRA LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR, CONSTITUYE EL:.', 'PRINCIPIO DE RAZONABILIDAD Y PROPORCIONALIDAD.', 'ART. 2', '185239'),
    (2536, 'SUB-2536', 'SBM5', 'PREVENIR, ERRADICAR Y SANCIONAR TODA FORMA DE VIOLENCIA PRODUCIDA EN EL ÁMBITO PÚBLICO Y PRIVADO CONTRA LAS MUJERES POR SU CONDICIÓN DE TALES, Y CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR, CONSTITUYE EL:.', 'EL OBJETO.', 'ART. 1', '185240'),
    (2537, 'SUB-2537', 'SBM5', 'LOS OPERADORES DE JUSTICIA Y LA POLICÍA NACIONAL DEL PERÚ, ANTE UN HECHO O AMENAZA DE VIOLENCIA, DEBEN ACTUAR EN FORMA OPORTUNA, SIN DILACIÓN POR RAZONES PROCEDIMENTALES,FORMALES O DE OTRA NATURALEZA, DISPONIENDO EL EJERCICIO DE LAS MEDIDAS DE PROTECCIÓN PREVISTAS EN LA LEY Y OTRAS NORMAS, CON LA FINALIDAD DE ATENDER EFECTIVAMENTE A LA VÍCTIMA, CONSTITUYE EL:.', 'PRINCIPIO DE INTERVENCIÓN INMEDIATA Y OPORTUNA.', 'ART. 2', '185241'),
    (2538, 'SUB-2538', 'SBM5', '¿QUÉ ENFOQUE HACE REFERENCIA EL TEXTO: CONSIDERA QUE LA NIÑEZ, LA JUVENTUD, LA ADULTEZ Y LA VEJEZ DEBEN TENER UNA CONEXION, PUES EN CONJUNTO ESTAN ABONANDO A UNA HISTORIA COUMN Y DEBEN FORTALECERSE GENERACIONALMENTE.', 'ENFOQUE GENERACIONAL.', 'ART. 3', '185242'),
    (2539, 'SUB-2539', 'SBM5', 'LAS DISPOSICIONES DE LA LEY N° 30364 SE APLICAN A TODOS LOS TIPOS DE VIOLENCIA CONTRA LAS MUJERES POR SU CONDICIÓN DE TALES Y CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR, CONSTITUYE EL:.', 'EL ÁMBITO DE APLICACIÓN DE LA LEY.', 'ART. 4', '185243'),
    (2540, 'SUB-2540', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES ES CUALQUIER ACCIÓN O CONDUCTA QUE LES CAUSA MUERTE, DAÑO O SUFRIMIENTO FÍSICO, SEXUAL O PSICOLÓGICO POR SU CONDICIÓN DE TALES, TANTO EN EL ÁMBITO:.', 'PÚBLICO COMO EN EL PRIVADO.', 'ART. 5', '185244'),
    (2541, 'SUB-2541', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES CUANDO TENGA LUGAR EN LA COMUNIDAD, ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'LA TORTURA', 'ART. 5', '185245'),
    (2542, 'SUB-2542', 'SBM5', 'LA VIOLENCIA CONTRA LAS MUJERES, LA QUE TENGA LUGAR EN LA COMUNIDAD, ES PERPETRADA POR CUALQUIER PERSONA Y COMPRENDE, ENTRE OTROS:.', 'EL ACOSO SEXUAL.', 'ART. 5', '185246'),
    (2543, 'SUB-2543', 'SBM5', '¿CON QUIÉN SE DEBA TENER ESPECIAL CONSIDERACIÓN EN LA VIOLENCIA CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR?', 'CON LOS NIÑOS.', 'ART. 6', '185248'),
    (2544, 'SUB-2544', 'SBM5', 'LA VIOLENCIA CONTRA CUALQUIER INTEGRANTE DEL GRUPO FAMILIAR SE PRODUCE EN EL CONTEXTO DE UNA RELACIÓN DE:.', 'PODER', 'ART. 6', '185250'),
    (2545, 'SUB-2545', 'SBM5', '¿CON QUIÉN SE DEBERÁ TENER ESPECIAL CONSIDERACIÓN EN LA VIOLENCIA CONTRA LOS INTEGRANTES DEL GRUPO FAMILIAR?.', 'CON LAS NIÑAS.', 'ART. 6', '185251'),
    (2546, 'SUB-2546', 'SBM5', 'SON SUJETOS DE PROTECCIÓN DE LA LEY, LOS MIEMBROS DEL GRUPO FAMILIAR, ENTIÉNDASE COMO TALES A:.', 'ASCENDIENTES Y DESCENDIENTES.', 'ART. 7', '185252'),
    (2547, 'SUB-2547', 'SBM5', 'SON ACCIONES DE NATURALEZA SEXUAL QUE COMETEN CONTRA UNA PERSONA SIN SU CONSENTIMIENTO O BAJO COACCIÓN. INCLUYEN ACTOS QUE NO INVOLUCRAN PENETRACIÓN O CONTACTO FÍSICO, SE REFIERE A:.', 'VIOLENCIA SEXUAL.', 'ART. 8', '185256'),
    (2548, 'SUB-2548', 'SBM5', 'EN LA VIOLENCIA SEXUAL SE CONSIDERAN TALES, LA EXPOSICIÓN A MATERIAL:.', 'PORNOGRÁFICO', 'ART. 8', '185257'),
    (2549, 'SUB-2549', 'SBM5', 'SE CONSIDERA VIOLENCIA SEXUAL A LAS ACCIONES DE NATURALEZA SEXUAL QUE SE COMETEN CONTRA UNA PERSONA SIN SU CONSENTIMIENTO O BAJO COACCIÓN. INCLUYEN ACTOS QUE NO INVOLUCRAN PENETRACIÓN O CONTACTO FÍSICO ALGUNO. ASIMISMO SE CONSIDERAN TALES LA EXPOSICIÓN O MATERIAL PORNOGRÁFICO Y QUE VULNERAN EL DERECHO DE LAS PERSONAS A DECIDIR VOLUNTARIAMENTE ACERCA DE SU VIDA SEXUAL O REPRODUCTIVA, A TRAVÉS DE:.', 'AMENAZAS', 'ART. 8', '185258'),
    (2550, 'SUB-2550', 'SBM5', 'LA VIOLENCIA ECONÓMICA O PATRIMONIAL ES LA ACCIÓN U OMISIÓN QUE SE DIRIGE A OCASIONAR UN MENOSCABO EN LOS RECURSOS ECONÓMICOS O PATRIMONIALES DE CUALQUIER PERSONA, A TRAVÉS DE LA EVASIÓN DEL CUMPLIMIENTO DE SUS:.', 'OBLIGACIONES ALIMENTARIAS.', 'ART. 8', '185259'),
    (2551, 'SUB-2551', 'SBM5', 'LAS MUJERES Y LOS INTEGRANTES DEL GRUPO FAMILIAR TIENEN DERECHO A UNA VIDA LIBRE DE VIOLENCIA, A SER VALORADOS Y EDUCADOS A ESTAR LIBRE DE TODA FORMA DE DISCRIMINACIÓN, ESTIGMATIZACIÓN Y DE PATRONES ESTEREOTIPADOS DE COMPORTAMIENTO, PRÁCTICAS SOCIALES Y CULTURALES BASADAS EN CONCEPTOS DE:.', 'INFERIORIDAD Y SUBORDINACIÓN.', 'ART. 9', '185260'),
    (2552, 'SUB-2552', 'SBM5', 'EL TRABAJADOR O TRABAJADORA QUE ES VÍCTIMA DE LA VIOLENCIA TIENE EL DERECHO A LA JUSTIFICACIÓN DE LAS INASISTENCIAS Y TARDANZAS AL CENTRO DE TRABAJO. PARA TAL EFECTO, SE CONSIDERAN DOCUMENTOS JUSTIFICATORIOS LA DENUNCIA QUE PRESENTE ANTE LA DEPENDENCIA POLICIAL O ANTE EL:.', 'MINISTERIO PÚBLICO.', 'ART. 11', '185261'),
    (2553, 'SUB-2553', 'SBM5', 'LA PERSONA VÍCTIMA DE LA VIOLENCIA A QUE SE REFIERE LA PRESENTE LEY TIENE, ENTRE OTROS, DERECHO A LA ATENCIÓN ESPECIALIZADA EN EL ÁMBITO EDUCATIVO DE LAS SECUELAS DE LA VIOLENCIA, DE MODO QUE EL SERVICIO EDUCATIVO RESPONDA A SUS NECESIDADES SIN DESMEDRO DE LA CALIDAD DEL MISMO, CONSTITUYE:.', 'DERECHOS EN EL CAMPO DE LA EDUCACIÓN.', 'ART. 12', '185262'),
    (2554, 'SUB-2554', 'SBM5', '¿CUÁL DE LOS SIGUIENTES SERVICIOS DEBE BRINDAR EL ESTADO A LAS VÍCTIMAS DE VIOLENCIA CONTRA LA MUJER O INTEGRANTE DEL GRUPO FAMILIAR, SEGÚN EL ARTÍCULO 10, DE MANERA GRATUITA E INMEDIATA?', 'ASISTENCIA JURÍDICA ESPECIALIZADA EN SU PROPIA LENGUA', 'ART. 10', '185274'),
    (2555, 'SUB-2555', 'SBM5', 'LA OBLIGACIÓN DE PROPORCIONAR INTÉRPRETES EN LENGUA DE SEÑAS PERUANA PARA LA ATENCIÓN DE DENUNCIAS DE PERSONAS CON DISCAPACIDAD AUDITIVA RECAE PRINCIPALMENTE EN:', 'LA POLICÍA NACIONAL DEL PERÚ', 'ART. 10', '185275'),
    (2556, 'SUB-2556', 'SBM5', 'SI UNA VÍCTIMA DE VIOLENCIA REQUIERE HOSPITALIZACIÓN Y MEDICAMENTOS, ¿ESTOS SERVICIOS DEBEN SER CUBIERTOS POR EL ESTADO SEGÚN EL ARTÍCULO 10?', 'SÍ, DE MANERA GRATUITA EN EL MARCO DE LA ATENCIÓN INTEGRAL', 'ART. 10', '185280'),
    (2557, 'SUB-2557', 'SBM5', '¿QUÉ ENTIDADES ESTÁN OBLIGADAS A INFORMAR, BAJO RESPONSABILIDAD, A LAS VÍCTIMAS SOBRE SUS DERECHOS Y MECANISMOS DE DENUNCIA?', 'MINISTERIO PÚBLICO, POLICÍA NACIONAL DEL PERÚ Y PODER JUDICIAL', 'ART. 10', '185282'),
    (2558, 'SUB-2558', 'SBM5', 'SOBRE LA EMISIÓN DE INFORMES PARA CALIFICACIÓN DEL DAÑO FÍSICO Y PSÍQUICO DE LA VÍCTIMA, ¿QUÉ INSTITUCIÓN FIJA LOS PARÁMETROS MÉDICO-LEGALES DE REFERENCIA?', 'INSTITUTO DE MEDICINA LEGAL Y CIENCIAS FORENSES DEL MINISTERIO PÚBLICO', 'ART. 10', '185283'),
    (2559, 'SUB-2559', 'SBM5', 'RESPECTO A LA RECEPCIÓN DE LA DECLARACIÓN DE LA VÍCTIMA, LA LEY ESTABLECE QUE DEBE SER:', 'RECIBIDA POR PERSONAL ESPECIALIZADO EN AMBIENTE QUE RESGUARDE DIGNIDAD E INTIMIDAD', 'ART. 10', '185287'),
    (2560, 'SUB-2560', 'SBM5', 'SEGÚN EL ARTÍCULO 10, ¿LA ATENCIÓN A VÍCTIMAS DE VIOLENCIA EN PROGRAMAS SOCIALES ESTÁ CONDICIONADA A?', 'CUMPLIMIENTO DE NORMATIVA VIGENTE Y CRITERIOS ESTABLECIDOS', 'ART. 10', '185292'),
    (2561, 'SUB-2561', 'SBM5', '¿CÚAL ES EL NÚMERO DE LA LEY CONTRA EL CRIMEN ORGANIZADO?.', 'LEY 30077.', 'LEY N° 30077', '185294'),
    (2562, 'SUB-2562', 'SBM5', 'LA LEY 30077-CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'DELITOS MONETARIOS.', 'ART. 3. NUM. 10', '185295'),
    (2563, 'SUB-2563', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:', 'DELITOS ADUANEROS.', 'ART. 3', '185296'),
    (2564, 'SUB-2564', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'MARCAJE O REGLAJE.', 'ART. 3. NUM. 16', '185297'),
    (2565, 'SUB-2565', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:', 'GENOCIDIO.', 'ART. 3. NUM. 17', '185298'),
    (2566, 'SUB-2566', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'PORNOGRAFÍA INFANTIL.', 'ART. 3. NUM. 6', '185299'),
    (2567, 'SUB-2567', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'EXTORSIÓN.', 'ART. 3. NUM. 7', '185300'),
    (2568, 'SUB-2568', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'HOMICIDIO CALIFICADO.', 'ART. 3', '185301'),
    (2569, 'SUB-2569', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'TRATA DE PERSONAS Y EXPLOTACION..', 'ART. 3', '185302'),
    (2570, 'SUB-2570', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'DELITOS INFOMATICOS PREVISTOS EN LA LEY PENAL.', 'ART. 3. NUM. 14', '185303'),
    (2571, 'SUB-2571', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'DELITOS AMBIENTALES', 'ART. 3. NUM. 1', '185304'),
    (2572, 'SUB-2572', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS:', 'CONTRA LA ADMINISTRACIÓN PÚBLICA', 'ART. 3. NUM. 18', '185305'),
    (2573, 'SUB-2573', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS:.', 'CONTRA LA SALUD PÚBLICA.', 'ART. 3. NUM. 12 Ley 30077 - Contra el Crimen Organizado', '185306'),
    (2574, 'SUB-2574', 'SBM5', 'EL ENUNCIADO:"FIJAR LAS REGLAS Y PROCEDIMIENTOS RELATIVOS A LA INVESTIGACIÓN, JUZGAMIENTO Y SANCIÓN DE LOS DELITOS COMETIDOS POR ORGANIZACIONES CRIMINALES", CORRESPONDE A:.', 'OBJETO DE LA LEY.', 'ART. 1', '185307'),
    (2575, 'SUB-2575', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE AL SIGUIENTE DELITO:.', 'TENENCIA, FABRICACIÓN, TRÁFICO ILÍCITO DE ARMAS, MUNICIONES Y EXPLOSIVOS', 'ART. 3. NUM. 11', '185308'),
    (2576, 'SUB-2576', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS CONTRA EL PATRIMONIO EN LAS MODALIDADES DELICTIVAS DE:.', 'ROBO AGRAVADO', 'ART. 3.', '185309'),
    (2577, 'SUB-2577', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS CONTRA EL PATRIMONIO EN LAS MODALIDADES DELICTIVAS DE:.', 'HURTO AGRAVADO.', 'ART. 3.', '185310'),
    (2578, 'SUB-2578', 'SBM5', 'LAS TÉCNICAS ESPECIALES DE INVESTIGACIÓN DEBEN RESPETAR, ESCRUPULOSAMENTE Y EN TODOS LOS CASOS, LOS PRINCIPIOS DE:', 'NECESIDAD, RAZONABILIDAD Y PROPORCIONALIDAD.', 'ART. 7. NUM. 2', '185312'),
    (2579, 'SUB-2579', 'SBM5', 'SE PUEDEN ADOPTAR TÉCNICAS ESPECIALES DE INVESTIGACIÓN SIEMPRE QUE RESULTEN:.', 'IDÓNEAS, NECESARIAS E INDISPENSABLES PARA EL ESCLARECIMIENTO DE LOS HECHOS MATERIA DE INVESTIGACIÓN.', 'ART. 7. NUM. 1', '185314'),
    (2580, 'SUB-2580', 'SBM5', 'LA INTERCEPTACIÓN POSTAL E INTERVENCIÓN DE LAS COMUNICACIONES.- SU TRÁMITE Y REALIZACIÓN DE ESTAS MEDIDAS TIENEN CARÁCTER:', 'RESERVADO E INMEDIATO.', 'ART. 8. NUM. 2', '185315'),
    (2581, 'SUB-2581', 'SBM5', 'SOLO SE INTERCEPTA, RETIENE E INCAUTA LA CORRESPONDENCIA VINCULADA AL DELITO OBJETO DE INVESTIGACIÓN VINCULADO A LA ORGANIZACIÓN CRIMINAL, PROCURANDO, EN LA MEDIDA DE LO POSIBLE:.', 'NO AFECTAR LA CORRESPONDENCIA DE TERCEROS NO INVOLUCRADOS.', 'ART. 9. NUM.1', '185316'),
    (2582, 'SUB-2582', 'SBM5', 'EN EL ÁMBITO DE LA PRESENTE LEY, LA GRABACIÓN MEDIANTE LA CUAL SE REGISTRE LA INTERVENCIÓN DE LAS COMUNICACIONES ES CUSTODIADA DEBIDAMENTE POR:.', 'EL FISCAL.', 'ART. 10. NUM. 1', '185317'),
    (2583, 'SUB-2583', 'SBM5', 'LAS COMUNICACIONES QUE SON IRRELEVANTES PARA LA INVESTIGACIÓN SON ENTREGADAS A LAS PERSONAS AFECTADAS CON LA MEDIDA, ORDENÁNDOSE, BAJO RESPONSABILIDAD:.', 'LA DESTRUCCIÓN DE CUALQUIER TRANSCRIPCIÓN O COPIA DE LAS MISMAS.', 'ART. 10. NUM. 2', '185318'),
    (2584, 'SUB-2584', 'SBM5', 'EN LA AUDIENCIA JUDICIAL DE REEXAMEN, UNA VEZ EJECUTADAS LAS TÉCNICAS ESPECIALES DE INVESTIGACIÓN PREVISTAS EN LOS ARTÍCULOS 9 Y 10, EL AFECTADO PUEDE INSTAR LA REALIZACIÓN DE LA:.', 'AUDIENCIA JUDICIAL DE REEXAMEN.', 'ART. 11', '185319'),
    (2585, 'SUB-2585', 'SBM5', 'ES UNA TÉCNICA ESPECIAL DE INVESTIGACIÓN, MEDIANTE EL CÚAL, UNA VEZ EMITIDA LA DISPOSICIÓN FISCAL QUE AUTORIZA SU PARTICIPACIÓN, QUEDAN FACULTADOS PARA PARTICIPAR EN EL TRÁFICO JURÍDICO Y SOCIAL, ADQUIRIR, POSEER O TRANSPORTAR BIENES DE CARÁCTER DELICTIVO, PERMITIR SU INCAUTACIÓN E INTERVENIR EN TODA ACTIVIDAD ÚTIL Y NECESARIA PARA LA INVESTIGACIÓN DEL DELITO QUE MOTIVÓ LA DILIGENCIA.', 'AGENTE ENCUBIERTO.', 'ART. 13', '185321'),
    (2586, 'SUB-2586', 'SBM5', 'TODO PROCESO SEGUIDO CONTRA INTEGRANTES DE UNA ORGANIZACIÓN CRIMINAL, PERSONAS VINCULADAS A ELLA O QUE ACTÚAN POR ENCARGO DE LA MISMA, SE CONSIDERA:.', 'COMPLEJO.', 'ART. 6', '185324'),
    (2587, 'SUB-2587', 'SBM5', 'SON DE APLICACIÓN LAS REGLAS Y EL PROCESO DE EXTINCIÓN DE DOMINIO PARA LOS BIENES SEÑALADOS EN EL ANTERIOR ARTÍCULO, SIEMPRE QUE SE PRESENTEN UNO O MÁS SUPUESTOS PREVISTOS EN EL ARTÍCULO 7 DEL DECRETO LEGISLATIVO 1373, DECRETO LEGISLATIVO SOBRE:.', 'EXTINCIÓN DE DOMINIO', 'ART. 18', '185326'),
    (2588, 'SUB-2588', 'SBM5', '¿QUÉ FUNCIONARIOS PÚBLICOS EJERCEN SUS FUNCIONES DE CONFORMIDAD CON LAS NORMAS Y LOS REGLAMENTOS QUE GARANTIZAN LA SEGURIDAD, CONSERVACIÓN, SEGUIMIENTO Y CONTROL DE LA CADENA DE CUSTODIA DE LOS BIENES SEÑALADOS EN EL ARTÍCULO 17 DE LA PRESENTE LEY?:.', 'EL FISCAL O LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 19. NUM. 1', '185327'),
    (2589, 'SUB-2589', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE ES LÍDER, JEFE O CABECILLA O EJERCE FUNCIONES DE ADMINISTRACIÓN, DIRECCIÓN Y SUPERVISIÓN DE LA ORGANIZACIÓN CRIMINAL.', 'ART. 22. NUM. 1, LIT. C Ley 30077 - Contra el Crimen Organizado', '185328'),
    (2590, 'SUB-2590', 'SBM5', 'EN LA SECCION DE AGRAVANTES ESPECIALES.- CUANDO? EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE FINANCIA LA ORGANIZACIÓN CRIMINAL', 'ART. 22', '185329'),
    (2591, 'SUB-2591', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE, EN CONDICIÓN DE INTEGRANTE DE LA ORGANIZACIÓN CRIMINAL O PERSONA VINCULADA A ELLA O QUE ACTÚA POR ENCARGO DE LA MISMA, ES FUNCIONARIO O SERVIDOR PÚBLICO.', 'ART. 22. NUM. 1, LIT. E', '185330'),
    (2592, 'SUB-2592', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE, EN CONDICIÓN DE INTEGRANTE DE LA ORGANIZACIÓN CRIMINAL O PERSONA VINCULADA A ELLA O QUE ACTÚA POR ENCARGO DE LA MISMA, UTILIZA A MENORES DE EDAD U OTROS INIMPUTABLES PARA LA COMISION DEL DELITO.', 'ART. 22. NUM. 1, LIT. G', '185332'),
    (2593, 'SUB-2593', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE HACE USO DE ARMAS DE GUERRA PARA COMETER LOS DELITOS A QUE SE REFIERE LA PRESENTE LEY.', 'ART. 22. NUM. 1, LIT. H', '185333'),
    (2594, 'SUB-2594', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO POR EL DELITO COMETIDO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS TREINTA Y CINCO AÑOS, EN LOS SIGUIENTES SUPUESTOS:.', 'SI EL AGENTE, EN CONDICIÓN DE INTEGRANTE DE LA ORGANIZACIÓN CRIMINAL O PERSONA VINCULADA A ELLA O QUE ACTÚA POR ENCARGO DE LA MISMA, COMETE EL DELITO DESDE EL INTERIOR DE UN ESTABLECIMIENTO PENITENCIARIO, PRIVADO DE SU LIBERTAD.', 'ART. 22', '185334'),
    (2595, 'SUB-2595', 'SBM5', 'SI CUALQUIERA DE LOS DELITOS PREVISTOS EN LA PRESENTE LEY HAN SIDO COMETIDOS EN EJERCICIO DE LA ACTIVIDAD DE UNA PERSONA JURÍDICA O VALIÉNDOSE DE SU ESTRUCTURA ORGANIZATIVA PARA FAVORECERLO, FACILITARLO O ENCUBRIRLO, EL JUEZ DEBE IMPONER, ATENDIENDO A LA GRAVEDAD Y NATURALEZA DE LOS HECHOS, LA RELEVANCIA DE LA INTERVENCIÓN DE LA PERSONA JURÍDICA EN EL DELITO Y LAS CARACTERÍSTICAS PARTICULARES DE LA ORGANIZACIÓN CRIMINAL, CUALQUIERA DE LAS SIGUIENTES CONSECUENCIAS ACCESORIAS DE FORMA:.', 'ALTERNATIVA O CONJUNTA', 'ART. 23. NUM. 1', '185335'),
    (2596, 'SUB-2596', 'SBM5', 'SI CUALQUIERA DE LOS DELITOS PREVISTOS EN LA PRESENTE LEY HAN SIDO COMETIDOS EN EJERCICIO DE LA ACTIVIDAD DE UNA PERSONA JURÍDICA O VALIÉNDOSE DE SU ESTRUCTURA ORGANIZATIVA PARA FAVORECERLO, FACILITARLO O ENCUBRIRLO, EL JUEZ DEBE IMPONER, ATENDIENDO A LA GRAVEDAD Y NATURALEZA DE LOS HECHOS, LA RELEVANCIA DE LA INTERVENCIÓN DE LA PERSONA JURÍDICA EN EL DELITO Y LAS CARACTERÍSTICAS PARTICULARES DE LA ORGANIZACIÓN CRIMINAL, CUALQUIERA DE LAS SIGUIENTES CONSECUENCIAS ACCESORIAS DE FORMA ALTERNATIVA O CONJUNTA:', 'MULTA POR UN MONTO NO MENOR DEL DOBLE NI MAYOR DEL TRIPLE DEL VALOR DE LA TRANSACCIÓN REAL.', 'ART. 23. NUM. 1, LIT. A', '185336'),
    (2597, 'SUB-2597', 'SBM5', 'SI CUALQUIERA DE LOS DELITOS PREVISTOS EN LA PRESENTE LEY HAN SIDO COMETIDOS EN EJERCICIO DE LA ACTIVIDAD DE UNA PERSONA JURÍDICA O VALIÉNDOSE DE SU ESTRUCTURA ORGANIZATIVA PARA FAVORECERLO, FACILITARLO O ENCUBRIRLO, EL JUEZ DEBE IMPONER, ATENDIENDO A LA GRAVEDAD Y NATURALEZA DE LOS HECHOS, LA RELEVANCIA DE LA INTERVENCIÓN DE LA PERSONA JURÍDICA Y LAS CARACTERÍSTICAS PARTICULARES DE LA ORGANIZACIÓN CRIMINAL, CUALQUIERA DE LAS SIGUIENTES CONSECUENCIAS ACCESORIAS DE FORMA ALTERNATIVA O CONJUNTA:.', 'SUSPENSIÓN DE ACTIVIDADES POR UN PLAZO NO MAYOR A CINCO AÑOS.', 'ART. 23. NUM. 1, LIT. C', '185338'),
    (2598, 'SUB-2598', 'SBM5', 'AGRAVANTES ESPECIALES.- EL JUEZ AUMENTA LA PENA HASTA EN UNA TERCERA PARTE POR ENCIMA DEL MÁXIMO LEGAL FIJADO, SIN QUE EN NINGÚN CASO PUEDA EXCEDER LOS SIGUIENTES AÑOS:.', 'TREINTA Y CINCO AÑOS.', 'ART. 22. NUM. 1', '185339'),
    (2599, 'SUB-2599', 'SBM5', 'ACTOS DE COOPERACIÓN O ASISTENCIA INTERNACIONAL.- EN ESPECIAL LOS ACTOS DE COOPERACION Y ASISTENCIA SON LOS SIGUIENTES:.', 'CUALQUIER OTRA FORMA DE COOPERACION O ASISTENCIA JUDICIAL AUTORIZADA POR EL DERECHO INTERNO.', 'ART. 28. NUM. 1', '185343'),
    (2600, 'SUB-2600', 'SBM5', 'ACTOS DE COOPERACIÓN O ASISTENCIA INTERNACIONAL.- EN ESPECIAL, LOS ACTOS DE COOPERACIÓN Y ASISTENCIA, SON LOS SIGUIENTES:.', 'EMITIR COPIA CERTIFICADA DE DOCUMENTOS.', 'ART. 28. NUM. 2 LIT.B', '185345')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

