INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2601 a 2700
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2601, 'SUB-2601', 'SBM5', 'LA LEY 30077 CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'CONTRA LA SALUD PÚBLICA', 'ART. 3. NUM. 13', '185346'),
    (2602, 'SUB-2602', 'SBM5', 'SEGÚN LA LEY 30077 CONTRA EL CRIMEN ORGANIZADO, QUIEN SE ENCARGA DEL DISEÑO, IMPLEMENTACIÓN Y ADMINISTRACIÓN DEL SISTEMA DE CONTROL REFORZADO DE INTERNOS DE CRIMINALIDAD ORGANIZADA (SISCRICO):.', 'EL INSTITUTO NACIONAL PENITENCIARIO (INPE).', 'ART. 25', '185347'),
    (2603, 'SUB-2603', 'SBM5', 'LA LEY CONTRA EL CRIMEN ORGANIZADO ES APLICABLE A LOS DELITOS DE:.', 'TRÁFICO ILÍCITO DE MIGRANTES', 'ART. 3. NUM. 15', '185348'),
    (2604, 'SUB-2604', 'SBM5', 'SEGÚN EL ARTÍCULO 2 DE LA LEY 30077, ¿CUÁL DE LAS SIGUIENTES CARACTERÍSTICAS ES ESENCIAL PARA CALIFICAR A UN GRUPO COMO ORGANIZACIÓN CRIMINAL?', 'QUE TENGA UNA ESTRUCTURA COMPLEJA, ROLES CORRELACIONADOS Y PERMANENCIA O INDEFINICIÓN EN EL TIEMPO PARA DELITOS SANCIONADOS CON PENAS DE CINCO AÑOS O MÁS.', 'ART. 2', '185349'),
    (2605, 'SUB-2605', 'SBM5', '¿QUÉ ELEMENTO DIFERENCIA A UN "GRUPO CON ESTRUCTURA DESARROLLADA", SEGÚN LA LEY 30077 RESPECTO A OTROS GRUPOS DELICTIVOS?', 'SUS MIEMBROS TIENEN DETERMINADOS ROLES Y CORRELACIONADOS ENTRE SI, NO HAN SIDO CONSTITUIDOS FORTUITAMENTE, LOGRANDO SU PERMANENCIA EN EL TIEMPO E INTEGRACIÓN EN LA ORGANIZACIÓN.', 'ART. 2', '185350'),
    (2606, 'SUB-2606', 'SBM5', 'RESPECTO AL CONCEPTO DE CAPACIDAD OPERATIVA EN LA ORGANIZACIÓN CRIMINAL, LA LEY 30077 ESTABLECE QUE:', 'CONSISTE EN LA SUMA DE MEDIOS Y RECURSOS IDONEOS, DE HECHO O DE DERECHO, IDÓNEOS PARA DESARROLLAR EL PROGRAMA CRIMINAL', 'ART. 2', '185351'),
    (2607, 'SUB-2607', 'SBM5', 'DE ACUERDO A LA LEY 30077, ¿CUÁL DE LOS SIGUIENTES DELITOS NO FORMARÍA PARTE DE LA DEFINICIÓN DE ORGANIZACIÓN CRIMINAL SI SU PENALIDAD MÍNIMA FUERA INFERIOR A CINCO AÑOS DE PRISIÓN?', 'DELITO DE INJURIA SIMPLE CON PENA MENOR A DOS AÑOS', 'ART. 2', '185352'),
    (2608, 'SUB-2608', 'SBM5', 'SELECCIONE LA AFIRMACIÓN CORRECTA SOBRE EL CONCEPTO DE DELITO GRAVE EN LA LEY 30077:', 'DELITOS SANCIONADOS CON PENA PRIVATIVA DE LIBERTAD MAYOR DE SEIS AÑOS.', 'ART. 2', '185354'),
    (2609, 'SUB-2609', 'SBM5', 'SEGÚN EL ARTÍCULO 2 DE LA LEY 30077, LA COMISIÓN DEL HECHO PUNIBLE POR ORGANIZACIÓN CRIMINAL SE ACREDITA CUANDO:', 'EXISTE COMPLEJA ESTRUCTURA DESARROLLADA Y CON MAYOR CAPACIDAD OPERATIVA, POTENCIALMENTE CAPAZ DE LLEVAR A CABO UN PROGRAMA CRIMINAL', 'ART. 2', '185355'),
    (2610, 'SUB-2610', 'SBM5', 'DE ACUERDO AL ARTÍCULO 2 DE LA LEY 30077, ¿QUÉ ELEMENTO ES EXIGIDO PARA CONSIDERAR LA EXISTENCIA DE UNA ORGANIZACIÓN CRIMINAL?', 'GRUPO CON ESTRUCTURA DESARROLLADA', 'ART. 2', '185358'),
    (2611, 'SUB-2611', 'SBM5', 'QUE NORMA APRUEBA EL PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL ESPECÍFICO DE CONTROL DE IDENTIDAD.', 'DECRETO SUPREMO N° 010-2018-JUS', 'P.A.I.E DE CONTROL DE IDENTIDAD', '185690'),
    (2612, 'SUB-2612', 'SBM5', 'ESTA DILIGENCIA DE CONTROL CONSISTE EN EL REQUERIMIENTO DE IDENTIFICACIÓN PERSONAL REALIZADO POR EFECTIVOS POLICIALES EN LA VÍA PÚBLICA O EN CUALQUIER OTRO LUGAR DONDE SE REALICE LA SOLICITUD CUANDO RESULTE NECESARIO PARA PREVENIR UN DELITO U… (MARQUE LA ALTERNATIVA CORRECTA)', 'OBTENER INFORMACIÓN ÚTIL PARA LA AVERIGUACIÓN DE UN HECHO PUNIBLE', 'P.A.I.E DE CONTROL DE IDENTIDAD. CONCEPTO', '185691'),
    (2613, 'SUB-2613', 'SBM5', 'ESTA DILIGENCIA DE CONTROL CONSISTE EN EL REQUERIMIENTO DE IDENTIFICACIÓN PERSONAL REALIZADO POR EFECTIVOS POLICIALES EN LA VÍA PÚBLICA O EN CUALQUIER OTRO LUGAR DONDE SE REALICE LA SOLICITUD CUANDO RESULTE NECESARIO PARA PREVENIR UN DELITO U OBTENER INFORMACIÓN ÚTIL PARA LA AVERIGUACIÓN DE UN HECHO PUNIBLE. PARA TAL EFECTO, EL PERSONAL POLICIAL… (MARQUE LA ALTERNATIVA CORRECTA)', 'PODRÁ REALIZAR LAS COMPROBACIONES PERTINENTES', 'P.A.I.E DE CONTROL DE IDENTIDAD. CONCEPTO', '185692'),
    (2614, 'SUB-2614', 'SBM5', 'BUSCA FORTALECER LA ACTUACIÓN POLICIAL CON MIRAS A EFECTUAR CONTROLES DE IDENTIDAD DENTRO DEL MARCO DE LOS PRINCIPIOS DE NECESIDAD, RAZONABILIDAD, PROPORCIONALIDAD Y RESPETO A LA PERSONA. EL PRESENTE ENUNCIADO CORRESPONDE AL:', 'OBJETO', 'P.A.I.E DE CONTROL DE IDENTIDAD. OBJETO', '185693'),
    (2615, 'SUB-2615', 'SBM5', 'BUSCA FORTALECER LA ACTUACIÓN POLICIAL CON MIRAS A EFECTUAR CONTROLES DE IDENTIDAD DENTRO DEL MARCO DE LOS PRINCIPIOS DE NECESIDAD, RAZONABILIDAD, PROPORCIONALIDAD Y RESPETO A LA PERSONA.', 'PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL ESPECÍFICO DE CONTROL DE IDENTIDAD', 'P.A.I.E DE CONTROL DE IDENTIDAD', '185694'),
    (2616, 'SUB-2616', 'SBM5', 'BUSCA FORTALECER LA ACTUACIÓN POLICIAL CON MIRAS A EFECTUAR CONTROLES DE IDENTIDAD DENTRO DEL MARCO DE LOS PRINCIPIOS DE: (MARQUE LA ALTERNATIVA CORRECTA)', 'NECESIDAD, RAZONABILIDAD, PROPORCIONALIDAD Y RESPETO A LA PERSONA', 'P.A.I.E DE CONTROL DE IDENTIDAD. OBJETO', '185695'),
    (2617, 'SUB-2617', 'SBM5', 'EL PRESENTE PROTOCOLO SE FOCALIZA EN EL PROCEDIMIENTO DE CONTROL DE IDENTIDAD POLICIAL, ASÍ COMO EN LOS DEMÁS PROCEDIMIENTOS EFECTUADOS POR LA POLICÍA NACIONAL FUERA O DENTRO DE LAS DEPENDENCIAS POLICIALES, EN EL MARCO DE LAS INTERVENCIONES REALIZADAS PARA LA PRESERVACIÓN DEL ORDEN INTERNO Y ............................ , ASÍ COMO PARA LA BÚSQUEDA Y ACOPIO DE INFORMACIÓN O ELEMENTOS ÚTILES PARA LA INVESTIGACIÓN (COMPLETE EL ENUNCIADO)', 'PREVENCIÓN DEL DELITO', 'P.A.I.E DE CONTROL DE IDENTIDAD. ALCANCE', '185696'),
    (2618, 'SUB-2618', 'SBM5', 'EL PERSONAL POLICIAL REQUERIRÁ A CUALQUIER PERSONA SU DOCUMENTO NACIONAL DE IDENTIDAD Y PODRÁ REALIZAR LAS VERIFICACIONES PERTINENTES EN EL LUGAR DONDE SE ENCUENTRE...', 'SIN NECESIDAD DE ORDEN FISCAL O JUDICIAL', 'P.A.I.E DE CONTROL DE IDENTIDAD. CONTROL DE IDENTIDAD EN EL LUGAR PÚBLICO', '185697'),
    (2619, 'SUB-2619', 'SBM5', 'EN EL CONTROL DE IDENTIDAD, SI EL/LA REQUERIDO/A NO EXHIBE DOCUMENTACIÓN ALGUNA O EL DOCUMENTO PRESENTADO GENERA DUDAS SOBRE SU AUTENTICIDAD O CORRESPONDENCIA DE LA IDENTIDAD, SEGÚN LA GRAVEDAD DEL HECHO INVESTIGADO O ÁMBITO DE LA OPERACIÓN POLICIAL PRACTICA, EL PERSONAL POLICIAL DEBERÁ:', 'DEBERÁ CONDUCIRLO/A A LA DEPENDENCIA POLICIAL MÁS CERCANA PARA FINES EXCLUSIVOS DE IDENTIFICACIÓN', 'P.A.I.E DE CONTROL DE IDENTIDAD. CONTROL DE IDENTIDAD EN EL LUGAR PÚBLICO', '185698'),
    (2620, 'SUB-2620', 'SBM5', 'EL PERSONAL POLICIAL PODRÁ REGISTRAR SUS VESTIMENTAS, EQUIPAJE O VEHÍCULO.', 'SI EXISTIERE FUNDADO MOTIVO QUE EL/LA REQUERIDO/A PUEDA ESTAR VINCULADO/A A LA COMISIÓN DE UN HECHO DELICTUOSO (ESTÉ IDENTIFICADO O NO)', 'P.A.I.E DE CONTROL DE IDENTIDAD. REALIZACIÓN DEL REGISTRO PERSONAL', '185699'),
    (2621, 'SUB-2621', 'SBM5', 'EL/LA RETENIDO/A NO PODRÁ SER INGRESADO/A A UNA CELDA O CALABOZO, NI ESTARÁ EN CONTACTO CON OTRAS: (MARQUE LA ALTERNATIVA CORRECTA) Protocolos de Actuación Interinstitucional', 'PERSONAS DETENIDAS', 'P.A.I.E DE CONTROL DE IDENTIDAD. DILIGENCIAS EN LA DEPENDENCIA POLICIAL', '185700'),
    (2622, 'SUB-2622', 'SBM5', 'EL PERSONAL POLICIAL, DEBERÁ OTORGAR A EL/LA RETENIDO/A NUEVAMENTE LAS FACILIDADES PARA ACREDITAR SU IDENTIDAD O PARA COMUNICAR A SU FAMILIA O PERSONA QUE INDIQUE SOBRE SU RETENCIÓN.', 'DENTRO DE LA DEPENDENCIA', 'P.A.I.E DE CONTROL DE IDENTIDAD. DILIGENCIAS EN LA DEPENDENCIA POLICIAL', '185701'),
    (2623, 'SUB-2623', 'SBM5', 'SI EN LA DEPENDENCIA POLICIAL EL/LA RETENIDO/A FUERE IDENTIFICADO/A ANTES DEL VENCIMIENTO DE LAS CUATRO HORAS, … (MARQUE LA ALTERNATIVA CORRECTA)', 'SE DEBERÁ PERMITIR SU RETIRO', 'P.A.I.E DE CONTROL DE IDENTIDAD. DILIGENCIAS EN LA DEPENDENCIA POLICIAL', '185702'),
    (2624, 'SUB-2624', 'SBM5', 'EN CASO EL/LA RETENIDO/A FUERE UN EXTRANJERO, EL PERSONAL POLICIAL DEBERÁ REALIZAR INMEDIATAMENTE LAS COORDINACIONES CON LAS INSTITUCIONES CORRESPONDIENTES (INTERPOL, DIVISIÓN DE EXTRANJERÍA - SEGURIDAD DEL ESTADO, CONSULADOS, EMBAJADAS, MIGRACIONES, ETC.) … (MARQUE LA ALTERNATIVA CORRECTA)', 'A FIN DE AGOTAR SU IDENTIFICACIÓN', 'P.A.I.E DE CONTROL DE IDENTIDAD. DILIGENCIAS EN LA DEPENDENCIA POLICIAL', '185703'),
    (2625, 'SUB-2625', 'SBM5', 'SI EL PERSONAL POLICIAL CONSTATA QUE EL/LA RETENIDO/A REGISTRA ALGUNA REQUISITORIA PENDIENTE, LO PONDRÁ A DISPOSICIÓN DE LA OFICINA DE REQUISITORIAS DE LA PNP MEDIANTE EL DOCUMENTO RESPECTIVO, SIN PERJUICIO DE COMUNICAR TAL SITUACIÓN A:', 'EL/LA FISCAL', 'P.A.I.E DE CONTROL DE IDENTIDAD. DILIGENCIAS EN LA DEPENDENCIA POLICIAL', '185704'),
    (2626, 'SUB-2626', 'SBM5', 'QUE NORMA APRUEBA EL PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA.', 'DECRETO SUPREMO N° 010-2018-JUS', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA', '185705'),
    (2627, 'SUB-2627', 'SBM5', 'ES AQUELLA INTERVENCIÓN FÍSICA, APREHENSIÓN O TOMA DE POSESIÓN SOBRE BIENES TANGIBLES E INTANGIBLES, QUE SE PRESUMEN, CONSTITUYEN OBJETO, CUERPO, INSTRUMENTOS, EFECTOS O GANANCIAS DEL DELITO EN EL MARCO DE UNA INVESTIGACIÓN PENAL, SUSCEPTIBLE DE SER DEVUELTO. EL PRESENTE CONCEPTO CORRESPONDE A:', 'INCAUTACIÓN', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. CONCEPTO DE INCAUTACIÓN', '185706'),
    (2628, 'SUB-2628', 'SBM5', 'ES AQUELLA INTERVENCIÓN FÍSICA, APREHENSIÓN O TOMA DE POSESIÓN SOBRE BIENES QUE CONSTITUYEN OBJETO DEL DELITO, CUANDO ATENDIENDO A SU NATURALEZA, NO CORRESPONDA SU ENTREGA O DEVOLUCIÓN. EL PRESENTE CONCEPTO CORRESPONDE A:', 'COMISO', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. CONCEPTO DE COMISO', '185707'),
    (2629, 'SUB-2629', 'SBM5', 'ES EL ACTO DE RECOJO Y TOMA DE POSESIÓN SOBRE BIENES QUE SE PRESUMEN, CONSTITUYEN OBJETO, CUERPO, INSTRUMENTOS, EFECTOS DEL DELITO QUE SE ENCUENTRAN VINCULADOS A LA COMISIÓN DE UN ILÍCITO PENAL. EL PRESENTE CONCEPTO CORRESPONDE A:', 'HALLAZGO', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. CONCEPTO DE HALLAZGO', '185708'),
    (2630, 'SUB-2630', 'SBM5', 'ES EL PROCEDIMIENTO DESTINADO A GARANTIZAR LA INDIVIDUALIZACIÓN, SEGURIDAD Y PRESERVACIÓN DE LOS ELEMENTOS MATERIALES Y EVIDENCIAS, RECOLECTADOS DE ACUERDO A SU NATURALEZA O INCORPORADOS EN TODA INVESTIGACIÓN DE UN HECHO PUNIBLE, DESTINADOS A GARANTIZAR SU AUTENTICIDAD, PARA LOS EFECTOS DEL PROCESO. LAS ACTAS, RÓTULOS, FORMULARIOS Y EMBALAJES FORMAN PARTE DE LA CADENA DE CUSTODIA. EL PRESENTE CONCEPTO CORRESPONDE A:', 'CADENA DE CUSTODIA', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. CONCEPTO DE CADENA DE CUSTODIA', '185709'),
    (2631, 'SUB-2631', 'SBM5', 'FORTALECER LA ACTUACIÓN INTERINSTITUCIONAL DE LOS OPERADORES DEL SISTEMA DE ADMINISTRACIÓN DE JUSTICIA PENAL DURANTE LOS PROCEDIMIENTOS DE INCAUTACIÓN, COMISO, HALLAZGO Y CADENA DE CUSTODIA. CORRESPONDE A:', 'OBJETO', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. OBJETO', '185710'),
    (2632, 'SUB-2632', 'SBM5', 'EL PERSONAL POLICIAL INTERVINIENTE LEVANTARÁ EL ACTA DE INCAUTACIÓN, DONDE SE DETALLARÁN E INDIVIDUALIZARÁN LOS BIENES OBJETO DE INCAUTACIÓN. SEGUIDAMENTE, SE INICIARÁ EL PROCEDIMIENTO DE: (MARQUE LA ALTERNATIVA CORRECTA)', 'CADENA DE CUSTODIA DE LOS BIENES INCAUTADOS', 'P.A.I.E PARA LA APLICACIÓN DE LA INCAUTACIÓN, COMISIÓN, HALLAZGO Y CADENA DE CUSTODIA. INCAUTACIÓN REALIZADA EN UNA INTERVENCIÓN EN FLAGRANCIA', '185711'),
    (2633, 'SUB-2633', 'SBM5', 'ES TODO ESPACIO FÍSICO, INCLUIDAS LAS ZONAS ADYACENTES, DONDE PRESUNTAMENTE SE HA PERPETRADO O SE HA DEJADO RASTROS DE UNO O MÁS HECHOS PUNIBLES, Y DONDE SE HALLAN INDICIOS Y EVIDENCIAS RELACIONADAS CON EL HECHO A INVESTIGAR. EL PRESENTE CONCEPTO CORRESPONDE A:', 'ESCENA DEL CRIMEN', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. CONCEPTO DE ESCENA DEL CRIMEN', '185712'),
    (2634, 'SUB-2634', 'SBM5', 'EL PERSONAL POLICIAL QUE TOMA CONOCIMIENTO DE UN HECHO DELICTIVO (NOTICIA CRIMINAL), DEBERÁ: (MARQUE LA ALTERNATIVA CORRECTA)', 'ANOTAR TODA LA INFORMACIÓN QUE SEA NECESARIA', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. CONOCIMIENTO Y VERIFICACIÓN', '185713'),
    (2635, 'SUB-2635', 'SBM5', 'PARA EL AISLAMIENTO DEBERÁN EMPLEAR UN MECANISMO IDÓNEO PARA SU DEMARCACIÓN Y ACORDONAMIENTO (CINTA PLÁSTICA, CORDELES, ETC.), DEFINIENDO ADECUADAMENTE SUS LÍMITES Y… (MARQUE LA ALTERNATIVA CORRECTA)', 'ESTABLECIENDO LAS VÍAS DE ENTRADA Y SALIDA DE LA ESCENA AISLADA', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. PROTECCIÓN DE LA ESCENA', '185714'),
    (2636, 'SUB-2636', 'SBM5', 'EL PERSONAL POLICIAL INTERVINIENTE DEBERÁ TOMAR LAS PREVISIONES DEL CASO ANTE POSIBLES CIRCUNSTANCIAS QUE PUEDAN DEGENERAR O CONTAMINAR LA ESCENA (LLUVIA, GRANIZO, FUEGO, GASOLINA, CALOR, ETC.), EVITANDO QUE SE PIERDAN O DETERIOREN LOS INDICIOS Y LAS EVIDENCIAS. TRATÁNDOSE DE LUGARES CERRADOS, DEBERÁ PROTEGER LOS ACCESOS, COMO PUERTAS, VENTANAS, FORADOS, PARA IMPEDIR EL PASO DE PERSONAS NO AUTORIZADAS. EN TODO MOMENTO PODRÁ … (MARQUE LA ALTERNATIVA CORRECTA)', 'SOLICITAR EL APOYO POLICIAL INMEDIATO', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. PROTECCIÓN DE LA ESCENA', '185715'),
    (2637, 'SUB-2637', 'SBM5', 'EL EQUIPO QUE TENDRÁ A SU CARGO EL PROCESAMIENTO DE LA ESCENA, ESTARÁ CONFORMADO POR: (MARQUE LA ALTERNATIVA CORRECTA)', 'EFECTIVOS POLICIALES DEL SISTEMA CRIMINALÍSTICO POLICIAL', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. PROCESAMIENTO E INVESTIGACIÓN DE LA ESCENA DEL CRIMEN', '185716'),
    (2638, 'SUB-2638', 'SBM5', 'EL EMBALAJE Y ROTULADO DE LOS INDICIOS Y EVIDENCIAS SE EFECTUARÁ TENIENDO EN CUENTA LA NATURALEZA DE LOS MISMOS, RESPETANDO LOS PRINCIPIOS DE:', 'LA CADENA DE CUSTODIA', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. PROCESAMIENTO E INVESTIGACIÓN DE LA ESCENA DEL CRIMEN', '185717'),
    (2639, 'SUB-2639', 'SBM5', 'EN CASO DE EXISTIR UN SOSPECHOSO, EL PERSONAL POLICIAL POLICÍA TOMARÁ EL CONTROL DE DICHA PERSONA TOMANDO LAS MEDIDAS DE SEGURIDAD CORRESPONDIENTES, A FIN DE EVITAR SU FUGA; DE SER EL CASO, … (MARQUE LA ALTERNATIVA CORRECTA)', 'PROCEDERÁ A DETENERLO', 'P.A.I.E DE PROTEC. E INVEST.N DE LA ESCENA DEL CRIMEN. PROCESAMIENTO E INVESTIGACIÓN DE LA ESCENA DEL CRIMEN', '185718'),
    (2640, 'SUB-2640', 'SBM5', 'QUE NORMA APRUEBA EL PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL ESPECÍFICO DE RECONOCIMIENTOS', 'DECRETO SUPREMO N° 010-2018-JUS', 'P.A.I.E DE RECONOCIMIENTOS', '185719'),
    (2641, 'SUB-2641', 'SBM5', 'DILIGENCIA QUE PERMITE IDENTIFICAR A UNA PERSONA, POR SUS RASGOS PROPIOS, VOZ, FISONOMÍA, MOVIMIENTOS, ETC., MEDIANTE ACTO FÍSICO, VIDEO O FOTOGRAFÍA, OTORGANDO ELEMENTOS PARA EL DESARROLLO DE UNA LÍNEA INVESTIGATIVA DETERMINADA. EL PRESENTE CONCEPTO SE REFIERE A:', 'RECONOCIMIENTO', 'P.A.I.E DE RECONOCIMIENTOS. CONCEPTO DE RECONOCIMIENTO', '185720'),
    (2642, 'SUB-2642', 'SBM5', 'FORTALECER LA ACTUACIÓN POLICIAL Y FISCAL RESPECTO A LA REALIZACIÓN DE LA DILIGENCIA DE RECONOCIMIENTO. ES EL OBJETIVO DEL PROTOCOLO DE: (MARQUE LA ALTERNATIVA CORRECTA)', 'ACTUACIÓN INTERINSTITUCIONAL ESPECÍFICO DE RECONOCIMIENTOS', 'P.A.I.E DE RECONOCIMIENTOS. OBJETIVO', '185721'),
    (2643, 'SUB-2643', 'SBM5', 'EN EL RECONOCIMIENTO DE PERSONAS. EL GRUPO DE PERSONAS SELECCIONADAS PARA SER PUESTAS A LA VISTA JUNTO A LA PERSONA A SER RECONOCIDA, EN LA MEDIDA DE LO POSIBLE DEBEN TENER ASPECTO EXTERIOR SEMEJANTE A ÉSTA ÚLTIMA, ASIGNÁNDOLES: (MARQUE LA ALTERNATIVA CORRECTA)', 'NÚMEROS VISIBLES Y CORRELATIVOS', 'P.A.I.E DE RECONOCIMIENTOS. RECONOCIMIENTO DE PERSONAS', '185722'),
    (2644, 'SUB-2644', 'SBM5', 'EL RECONOCIMIENTO POR FOTOGRAFÍAS NO IMPIDE QUE POSTERIORMENTE, SE PUEDA REALIZAR', 'LA DILIGENCIA DE RECONOCIMIENTO EN FORMA PERSONAL', 'P.A.I.E DE RECONOCIMIENTOS. RECOCIMIENTO POR FOTOGRAFÍAS', '185723'),
    (2645, 'SUB-2645', 'SBM5', 'DE LA MULTIPLICIDAD DE RECONOCIMIENTOS, CUANDO LA PERSONA DEBA RECONOCER A VARIAS: (MARQUE LA ALTERNATIVA CORRECTA)', 'LA DILIGENCIA SE REALIZARÁ EN UN SOLO ACTO', 'P.A.I.E DE RECONOCIMIENTOS. MULTIPLICIDAD DE RECONOCIMIENTOS', '185724'),
    (2646, 'SUB-2646', 'SBM5', 'CUANDO VARIAS PERSONAS DEBAN RECONOCER A UNA SOLA.', 'EL RECONOCIMIENTO SE PRACTICA POR SEPARADO', 'P.A.I.E DE RECONOCIMIENTOS. MULTIPLICIDAD DE RECONOCIMIENTOS', '185725'),
    (2647, 'SUB-2647', 'SBM5', 'QUE NORMA APRUEBA EL PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN.', 'DECRETO SUPREMO N° 010-2018-JUS', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN Protocolos de Actuación Interinstitucional', '185726'),
    (2648, 'SUB-2648', 'SBM5', 'EL PERSONAL POLICIAL CUANDO CONSIDERE QUE UNA PERSONA OCULTE EN SU CUERPO O ÁMBITO CORPORAL, BIENES RELACIONADOS CON EL DELITO, DEBERÁ: (MARQUE LA ALTERNATIVA CORRECTA)', 'SOLICITARÁ A LA PERSONA A QUE EXHIBA Y ENTREGUE EL BIEN BUSCADO', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. DESARROLLO DEL REGISTRO PERSONAL', '185727'),
    (2649, 'SUB-2649', 'SBM5', 'ANTES DE INICIAR EL REGISTRO SE EXPRESARÁ A EL/LA INTERVENIDO/A LAS RAZONES DE SU EJECUCIÓN, Y SE LE INDICARÁ QUE TIENE DERECHO DE HACERSE ASISTIR EN ESE ACTO POR UNA PERSONA DE SU CONFIANZA, SIEMPRE QUE ÉSTA SE PUEDA UBICAR RÁPIDAMENTE Y SEA MAYOR DE EDAD. SI LA PERSONA ES UBICADA, PERO SU ESPERA PONE EN RIESGO LA FINALIDAD DE LA MEDIDA:', 'EL REGISTRO SE REALIZARÁ SIN SU PARTICIPACIÓN, DEJÁNDOSE CONSTANCIA DE ELLO', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. DESARROLLO DEL REGISTRO PERSONAL', '185728'),
    (2650, 'SUB-2650', 'SBM5', 'EN LOS CASOS EN QUE LA PERSONA INTERVENIDA NO ACEPTE SOMETERSE AL REGISTRO POR UN PERSONAL POLICIAL DE OTRO SEXO Y, NO EXISTA RIESGO DE PÉRDIDA DE LA FUENTE DE PRUEBA, DEBERÁ:', 'SER CONDUCIDA A LA DEPENDENCIA POLICIAL MÁS CERCANA, DANDO CUENTA INMEDIATAMENTE AL FISCAL', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. DESARROLLO DEL REGISTRO PERSONAL', '185729'),
    (2651, 'SUB-2651', 'SBM5', 'EL REGISTRO PERSONAL NO COMPRENDE EXTRACCIÓN DE MUESTRAS COMO PRUEBAS DE ANÁLISIS SANGUÍNEO, GENÉTICO-MOLECULARES; ASÍ COMO, EXPLORACIONES RADIOLÓGICAS, U OTRAS MÍNIMAS INTERVENCIONES CORPORALES PARA OBSERVACIÓN; SALVO QUE LA PERSONA DEBIDAMENTE INFORMADA LO AUTORICE.', 'EL REGISTRO PERSONAL', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. LÍMITES AL REGISTRO PERSONAL', '185730'),
    (2652, 'SUB-2652', 'SBM5', 'SI DEL REGISTRO PERSONAL SE PRESUME QUE LA PERSONA LLEVA DENTRO DE SU CUERPO ELEMENTOS O INDICIOS DE PRUEBA:', 'EL PERSONAL POLICIAL DEBERÁ DAR CUENTA A EL/LA FISCAL, A FIN QUE ÉSTE ÚLTIMO SOLICITE EL REQUERIMIENTO CORRESPONDIENTE ANTE EL/LA JUEZ/A COMPETENTE', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. INTERVENCIÓN CORPORAL', '185731'),
    (2653, 'SUB-2653', 'SBM5', 'ES AQUELLA INJERENCIA CON EL PROPÓSITO DE BUSCAR O HALLAR EFECTOS O ELEMENTOS VINCULADOS AL DELITO, SIN QUE ELLO IMPLIQUE EL EXAMEN DEL CUERPO.', 'EL REGISTRO', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. CONCEPTO DE REGISTRO', '185732'),
    (2654, 'SUB-2654', 'SBM5', 'EXCEPCIONALMENTE CUANDO HAYA URGENCIA Y PELIGRO EN LA DEMORA Y, NO SE PUEDA ESPERAR LA ORDEN JUDICIAL:ROCEDE A:.', 'EL/LA FISCAL ORDENARÁ LA INTERVENCIÓN CORPORAL', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. INTERVENCIÓN CORPORAL', '185733'),
    (2655, 'SUB-2655', 'SBM5', 'SE PRODUCE ANTE LA ENTREGA VOLUNTARIA Y ESPONTÁNEA DE LOS EFECTOS O ELEMENTOS VINCULADOS AL DELITO, O COMO CONSECUENCIA DE LA SOLICITUD DE LA AUTORIDAD COMPETENTE.', 'LA RECEPCIÓN', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. CONCEPTO DE RECEPCIÓN', '185734'),
    (2656, 'SUB-2656', 'SBM5', 'SI SE VERIFICA QUE EN EL VEHÍCULO SE ENCUENTRAN BIENES, EFECTOS O INSTRUMENTOS VINCULADOS A LA COMISIÓN DE UN DELITO, SE PROCEDERÁ A INFORMAR A EL/LA DETENIDO/A LA CAUSA:', 'EL MOTIVO DE SU DETENCIÓN Y EL DELITO QUE SE LE ATRIBUYE ASÍ COMO, LOS DERECHOS ESTABLECIDOS EN EL ARTÍCULO 71 DEL CPP', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. REGISTRO VEHICULAR EN LA BÚSQUEDA DE BIENES U OBJETOS', '185735'),
    (2657, 'SUB-2657', 'SBM5', 'RESPECTO AL REGISTRO DE VEHÍCULOS VINCULADOS CON DELITOS. EL PERSONAL POLICIAL PROCEDERÁ A LEVANTAR LAS SIGUIENTES ACTAS:', 'ACTA DE SITUACIÓN VEHICULAR Y ACTA DE REGISTRO VEHICULAR', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. REGISTRO DE VEHÍCULOS VINCULADOS CON DELITOS', '185736'),
    (2658, 'SUB-2658', 'SBM5', 'CULMINADAS LAS DILIGENCIAS NECESARIAS EN EL LUGAR DE LOS HECHOS, EL VEHÍCULO SERÁ TRASLADADO: (MARQUE LA ALTERNATIVA CORRECTA) Protocolos de Actuación Interinstitucional', 'A LA DEPENDENCIA POLICIAL QUE TENDRÁ A SU CARGO LA INVESTIGACIÓN', 'P.A.I.E PARA LA APLICACIÓN DEL REGISTRO Y RECEPCIÓN. REGISTRO DE VEHÍCULOS VINCULADOS CON DELITOS', '185737'),
    (2659, 'SUB-2659', 'SBM5', 'QUE NORMA APRUEBA EL PROTOCOLO DE ACTUACIÓN INTERINSTITUCIONAL ESPECÍFICO PARA LA APLICACIÓN DEL PROCESO INMEDIATO REFORMADO.', 'DECRETO SUPREMO N° 009-2018-JUS', 'P.A.I.E PARA LA APLICACIÓN DEL PROCESO INMEDIATO REFORMADO', '185738'),
    (2660, 'SUB-2660', 'SBM5', 'FORTALECER LA ACTUACIÓN DE LOS OPERADORES DEL SISTEMA DE JUSTICIA PENAL EN LA APLICACIÓN DEL PROCESO INMEDIATO EN CASOS DE FLAGRANCIA Y OTROS SUPUESTOS (JUECES/ZAS, FISCALES, DEFENSORES/AS. POLICÍAS Y PROCURADORES/AS). EL PRESENTE ENUNCIADO CORRESPONDE A:', 'OBJETIVO', 'P.A.I.E PARA LA APLICACIÓN DEL PROCESO INMEDIATO REFORMADO. OBJETIVO', '185739'),
    (2661, 'SUB-2661', 'SBM5', '¿CUÁL ES EL ÁMBITO DE ACTUACIÓN JURISDICCIONAL DE LA INVESTIGACIÓN REALIZADA POR LA POLICÍA NACIONAL DEL PERÚ BAJO LA CONDUCCIÓN JURÍDICA DEL MINISTERIO PÚBLICO SEGÚN LA MODIFICACIÓN DE LA LEY 32130:', 'LA INVESTIGACIÓN POLICIAL, BAJO CONDUCCIÓN DEL MINISTERIO PÚBLICO, NO TIENE CARÁCTER JURISDICCIONAL, DEBIENDO REQUERIRSE DECISIÓN JURISDICCIONAL AL ÓRGANO COMPETENTE CUANDO SEA INDISPENSABLE.', 'ART. ÚNICO art. IV', '184850'),
    (2662, 'SUB-2662', 'SBM5', 'SEGÚN LA LEY 32130, ¿CUÁL ES LA FUNCIÓN PRIMORDIAL DEL MINISTERIO PÚBLICO EN RELACIÓN CON LA POLICÍA NACIONAL DURANTE LA INVESTIGACIÓN PRELIMINAR DE UN DELITO:', 'DIRIGIR JURÍDICAMENTE LA INVESTIGACIÓN ORIENTANDO LEGALMENTE LAS ACCIONES DE LA POLICÍA NACIONAL DEL PERÚ DENTRO DE LOS PARÁMETROS DE LA LEY', 'ART. ÚNICO art. IV', '184851'),
    (2663, 'SUB-2663', 'SBM5', 'EN VIRTUD DE LA MODIFICACIÓN LEGAL REFERIDA, QUÉ DEBER FUNDAMENTAL RECAE SOBRE EL MINISTERIO PÚBLICO RESPECTO A LA CARGA DE LA PRUEBA EN EL PROCESO PENAL:', 'ASUMIR LA CARGA DE LA PRUEBA. ACTUANDO CON OBJETIVIDAD, INDAGANDO POR INTERMEDIO DE LA POLICIA TANTO HECHOS CONSTITUTIVOS DEL DELITO, QUE DETERMINEN LA RESPONSABILIDAD O INOCENCIA DEL IMPUTADO.', 'ART. ÚNICO art. IV', '184852'),
    (2664, 'SUB-2664', 'SBM5', 'ANTE QUÉ SITUACIÓN LA POLICÍA NACIONAL Y EL MINISTERIO PÚBLICO DEBEN REQUERIR LA INTERVENCIÓN DEL ÓRGANO JURISDICCIONAL COMPETENTE DURANTE LA ETAPA DE INVESTIGACIÓN PRELIMINAR:', 'SIEMPRE QUE SE REQUIERA UNA DECISIÓN DE NATURALEZA JURISDICCIONAL QUE EXCEDA LAS COMPETENCIAS LEGALES, MOTIVANDO DEBIDAMENETE SU PETICIÓN.', 'ART. ÚNICO art. IV', '184853'),
    (2665, 'SUB-2665', 'SBM5', 'DE ACUERDO CON LA LEY 32130, ¿CUÁL ES LA RELACIÓN JERÁRQUICA Y FUNCIONAL ENTRE EL MINISTERIO PÚBLICO Y LA POLICÍA NACIONAL EN EL MARCO DE LA INVESTIGACIÓN DEL DELITO:', 'EL MINISTERIO PÚBLICO ASUME LA CONDUCCIÓN JURÍDICA DE LA INVESTIGACIÓN Y LA POLICÍA NACIONAL REALIZA LA INVESTIGACIÓN PRELIMINAR CONFORME A SU LEYES Y REGLAMENTOS.', 'ART. ÚNICO art. IV', '184854'),
    (2666, 'SUB-2666', 'SBM5', '¿CUÁL DE LAS SIGUIENTES SITUACIONES CONSTITUYE UNA CAUSAL DE INHIBICIÓN OBLIGATORIA PARA JUECES EN UN PROCESO PENAL SEGÚN LA MODIFICACIÓN INTRODUCIDA POR LA LEY 32130 AL ARTÍCULO ÚNICO DEL D.LEG. 957:', 'QUE EL JUEZ HAYA ACONSEJADO SOBRE LA CAUSA A CUALQUIERA DE LAS PARTES DEL PROCESO, AFECTANDO POTENCIALMENTE SU IMPARCIALIDAD.', 'ART. ÚNICO art. 53', '184855'),
    (2667, 'SUB-2667', 'SBM5', 'RESPECTO A LA INHIBICIÓN DE FISCALES SEÑALADA EN EL ART 53 ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA TENIENDO EN CUENTA LA LEY 32130:', 'DICHA INHIBICIÓN ALCANZA A LOS FISCALES EN LOS MISMOS TÉRMINOS QUE A LOS JUECES Y SU INOBSERVANCIA CONSTITUYE FALTA MUY GRAVE SEGÚN LA LEY 29277.', 'ART. ÚNICO art. 53', '184856'),
    (2668, 'SUB-2668', 'SBM5', 'EN EL MARCO DE LA LEY 32130, QUE MODIFICA EL ARTÍCULO 54 DEL CÓDIGO PROCESAL PENAL SOBRE RECUSACIONES, ¿EN QUÉ MOMENTO PUEDE SER INTERPUESTA UNA RECUSACIÓN DURANTE EL PROCEDIMIENTO RECURSAL Y CUÁL ES LA OBLIGACIÓN PROCESAL RESPECTO AL PLAZO PARA LAS PARTES:', 'DEBE SER INTERPUESTA HASTA UN DÍA HÁBIL ANTES DE LA AUDIENCIA DE VISTA DE LA CAUSA Y EL ÓRGANO REVISOR DEBE CONCEDER EL PLAZO DE TRES DÍAS A LAS PARTES PARA RECUSAR A LOS JUECES DE REVISIÓN. Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', 'ART. ÚNICO art. 54', '184857'),
    (2669, 'SUB-2669', 'SBM5', 'SEGÚN LAS MODIFICACIONES INTRODUCIDAS AL ARTÍCULO 54 DEL CÓDIGO PROCESAL PENAL POR LA LEY 32130, ¿QUÉ IMPLICANCIAS TIENE PARA EL JUEZ NO INHIBIRSE DE OFICIO ANTE LA VERIFICACIÓN DE UNA CAUSAL DE INHIBICIÓN DESPUÉS DEL INICIO DE LA AUDIENCIA Y BAJO QUÉ LEY SE TIPIFICA DICHA CONDUCTA:', 'LA OMISIÓN DE INHIBICIÓN DE OFICIO DEL JUEZ CONSTITUYE UNA FALTA MUY GRAVE PREVISTA EN LA LEY 29277, LEY DE LA CARRERA JUDICIAL.', 'ART. ÚNICO art. 54', '184858'),
    (2670, 'SUB-2670', 'SBM5', '¿SEGÚN EL ARTÍCULO 60 MODIFICADO POR LA LEY 32130, CUÁL ES LA FUNCIÓN CENTRAL DEL FISCAL EN LA INVESTIGACIÓN PRELIMINAR DEL DELITO:', 'EL FISCAL CONDUCE JURÍDICAMENTE LA INVESTIGACIÓN PRELIMINAR, LA CUAL ES LLEVADA A CABO POR LA POLICÍA NACIONAL DEL PERÚ.', 'ART. ÚNICO art. 60', '184859'),
    (2671, 'SUB-2671', 'SBM5', 'CONFORME AL ARTÍCULO 60 DEL CÓDIGO PROCESAL PENAL TRAS LA MODIFICACIÓN POR LA LEY 32130, ¿BAJO QUÉ PRINCIPIO DEBE EL FISCAL CONDUCIR LA INVESTIGACIÓN PREPARATORIA DEL DELITO:', 'BAJO EL PRINCIPIO DE LEGALIDAD, ASEGURANDO LA CORRECTA APLICACIÓN DE LA NORMA', 'ART. ÚNICO art. 60', '184860'),
    (2672, 'SUB-2672', 'SBM5', '¿CUÁL ES EL PLAZO MÁXIMO QUE TIENE EL FISCAL PARA DISPONER EL INICIO DE LA INVESTIGACIÓN PRELIMINAR EN CASO DE DELITOS DE TRÁFICO ILÍCITO DE DROGAS, TERRORISMO, SICARIATO, EXTORSIÓN, SECUESTRO, FEMINICIDIO Y CRIMINALIDAD ORGANIZADA:', 'VEINTICUATRO HORAS', 'ART. ÚNICO art. 61', '184861'),
    (2673, 'SUB-2673', 'SBM5', 'SEGÚN EL ARTÍCULO PROCESADO, ¿EN QUÉ MOMENTO INTERVIENE EL FISCAL DE MANERA PERMANENTE EN LA INVESTIGACIÓN A CARGO DE LA POLICÍA NACIONAL DEL PERÚ:', 'A PARTIR DE LA FORMALIZACIÓN DE LA INVESTIGACIÓN PREPARATORIA Y DURANTE TODO EL DESARROLLO DEL PROCESO', 'ART. ÚNICO art. 61', '184862'),
    (2674, 'SUB-2674', 'SBM5', '¿QUÉ DEBE PROCURAR EL FISCAL AL INDAGAR POR INTERMEDIO DE LA POLICÍA NACIONAL DEL PERÚ, EN CASO NO EXISTA DETENIDO NI FLAGRANCIA:', 'INVESTIGAR TANTO CIRCUNSTANCIAS QUE COMPRUEBEN LA IMPUTACIÓN, COMO LAS QUE EXIMAN O ATENÚEN LA RESPONSABILIDAD DEL IMPUTADO.', 'ART. ÚNICO art. 61', '184863'),
    (2675, 'SUB-2675', 'SBM5', '¿CUÁL DE LAS SIGUIENTES ACCIONES ES UNA ATRIBUCIÓN Y/O OBLIGACION DIRECTA DEL FISCAL, CONFORME AL ARTÍCULO 61 DE LA PRESENTE LEY:', 'SOLICITAR AL JUEZ LAS MEDIDAS QUE CONSIDERE NECESARIAS CUANDO CORRESPONDA HACERLO', 'ART. ÚNICO art. 61', '184864'),
    (2676, 'SUB-2676', 'SBM5', 'RESPECTO A LAS ATRIBUCIONES Y OBLIGACIONES (ART61), EL FISCAL, MARQUE LA ALTERNATIVA CORRECTA, DE CONFORMIDAD A LA NORMA COMENTADA:', 'TIENE LEGITIMACIÓN PARA INTERPONER LOS RECURSOS Y MEDIOS DE IMPUGNACIÓN QUE LA LEY ESTABLECE', 'ART. ÚNICO art. 61', '184865'),
    (2677, 'SUB-2677', 'SBM5', '¿CUÁL ES EL ROL INICIAL QUE DEBE ASUMIR EL FISCAL CUANDO RECIBE NOTICIA DE LA COMISIÓN DE UN DELITO, CONFORME AL ARTÍCULO 65 DEL CÓDIGO PROCESAL PENAL MODIFICADO POR LA LEY 32130?:', 'DISPONER DE FORMA INMEDIATA QUE LA POLICÍA NACIONAL DEL PERÚ REALICE LAS DILIGENCIAS PRELIMINARES.', 'ART. ÚNICO art. 65', '184866'),
    (2678, 'SUB-2678', 'SBM5', 'DE ACUERDO CON EL ARTÍCULO 65, CUANDO EL FISCAL DISPONE EL INICIO DE LA INVESTIGACIÓN PRELIMINAR, ¿QUÉ DEBE PRECISARSE NECESARIAMENTE?:', 'EL OBJETO, LOS PLAZOS Y LAS FORMALIDADES ESPECÍFICAS APLICABLES. Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', 'ART. ÚNICO art. 65', '184867'),
    (2679, 'SUB-2679', 'SBM5', 'SEGÚN LA MODIFICACIÓN INTRODUCIDA POR LA LEY 32130, ¿A QUIÉN CORRESPONDE DEFINIR LA ESTRATEGIA OPERATIVA EN LA INVESTIGACIÓN DEL DELITO?:', 'A LA POLICÍA NACIONAL DEL PERÚ.', 'ART. ÚNICO art. 65', '184868'),
    (2680, 'SUB-2680', 'SBM5', '¿QUÉ ASPECTO DEBEN GARANTIZAR TANTO EL FISCAL COMO LA POLICÍA NACIONAL DEL PERÚ DURANTE LA INVESTIGACIÓN DEL DELITO, SEGÚN EL ARTÍCULO 65 DE LA LEY N°32130?:', 'EL DERECHO DE DEFENSA DEL IMPUTADO Y SUS DEMAS DERECHOS FUNDAMENTALES.', 'ART. ÚNICO art. 65', '184869'),
    (2681, 'SUB-2681', 'SBM5', '¿CUÁL ES LA RELACIÓN ENTRE LA ESTRATEGIA JURÍDICA Y LA ESTRATEGIA OPERATIVA SEGÚN LA LEY 32130?:', 'LA ESTRATEGIA JURÍDICA ES COMPETENCIA DEL FISCAL Y LA OPERATIVA DE LA POLICÍA, PERO DEBEN SER PROGRAMADAS Y COORDINADAS EN CONJUNTO.', 'ART. ÚNICO art. 65', '184870'),
    (2682, 'SUB-2682', 'SBM5', 'EN LA INVESTIGACIÓN DEL DELITO CONFORME AL ARTÍCULO 65, ¿QUÉ DEBE HACER EL FISCAL RESPECTO A LAS DILIGENCIAS PRACTICADAS POR LA POLICÍA NACIONAL DEL PERÚ?:', 'REALIZAR LAS FORMALIDADES ESPECIFICAS QUE DEBEN REUNIR LOS ACTOS DE INVESTIGACION PARA GARANTIZAR SU VALIDEZ.', 'ART. ÚNICO art. 65', '184871'),
    (2683, 'SUB-2683', 'SBM5', 'UNA DE LAS OBLIGACIONES DEL FISCAL AL INICIAR UNA INVESTIGACIÓN PRELIMINAR, SEGÚN EL ARTÍCULO 65, ES:', 'PRECISAR EL OBJETO Y LOS PLAZOS DE LA INVESTIGACIÓN.', 'ART. ÚNICO art. 65', '184872'),
    (2684, 'SUB-2684', 'SBM5', 'RESPECTO A LA GARANTÍA DE LOS DERECHOS FUNDAMENTALES DEL IMPUTADO DURANTE LA INVESTIGACIÓN, EL ARTÍCULO 65 ESTABLECE QUE:', 'ES RESPONSABILIDAD DEL FISCAL Y LA POLICÍA NACIONAL DEL PERÚ.', 'ART. ÚNICO art. 65', '184873'),
    (2685, 'SUB-2685', 'SBM5', 'PARA LA INVESTIGACION DEL DELITO, CORRESPONDE LA ESTRASTEGIA JURIDICA Y OPERATIVA, PARA TAL FIN PROGRAMAN EL EMPLEO DE PAUTAS, TÉCNICAS Y MEDIOS DE INVESTIGACIÓN, EL ARTÍCULO 65 ESTABLECE QUE:', 'DEBEN PROGRAMARSE Y COORDINARSE DE MANERA CONJUNTA ENTRE EL FISCAL Y LA POLICÍA NACIONAL DEL PERÚ.', 'ART. ÚNICO art. 65', '184875'),
    (2686, 'SUB-2686', 'SBM5', '¿CUÁL ES LA CONDICIÓN ESENCIAL PARA QUE LA POLICÍA NACIONAL DEL PERÚ PUEDA RECIBIR LA MANIFESTACIÓN DE LOS PRESUNTOS AUTORES O PARTÍCIPES DE UN DELITO DURANTE LA INVESTIGACIÓN?:', 'OBLIGATORIEDAD DE LA PRESENCIA DEL ABOGADO DEFENSOR DE ELECCIÓN DEL INVESTIGADO, O DEL DEFENSOR PÚBLICO CORRESPONDIENTE.', 'ART. ÚNICO art. 68', '184876'),
    (2687, 'SUB-2687', 'SBM5', 'RESPECTO AL REGISTRO DE LAS MANIFESTACIONES DE LOS PRESUNTOS AUTORES O PARTÍCIPES POR LA POLICÍA NACIONAL DEL PERÚ, SEGÚN LA NORMA ANALIZADA, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA?:', 'EL REGISTRO DE LAS DECLARACIONES DEBE REALIZARSE EN DISPOSITIVOS O EQUIPOS AUDIOVISUALES.', 'ART. ÚNICO art. 67', '184877'),
    (2688, 'SUB-2688', 'SBM5', 'SEGÚN EL ARTÍCULO 68 MODIFICADO, ¿CÓMO DEBE PROCEDERSE EN CASO EL FISCAL TENGA CONOCIMIENTO DE LA DILIGENCIA POLICIAL DE MANIFESTACIÓN PERO NO PUEDA ASISTIR PRESENCIALMENTE?:', 'EL FISCAL PUEDE PARTICIPAR DE MANERA VIRTUAL, DEBIÉNDOSE DEJAR CONSTANCIA DE SU PARTICIPACIÓN.', 'ART. ÚNICO art. 68', '184878'),
    (2689, 'SUB-2689', 'SBM5', 'DE TODAS LAS DILIGENCIAS DE INVESTIGACIÓN REALIZADAS POR LA POLICÍA NACIONAL DEL PERÚ BAJO CONDUCCIÓN FISCAL, ¿QUE DOCUMENTOS FORMULARAN RESPETANDO LAS FORMALIDADES PREVISTAS PARA LA INVESTIGACION?:', 'LAS ACTAS DETALLADAS LAS QUE ENTREGARA AL FISCAL Y EMITIRA EL INFORME POLICIAL.', 'ART. ÚNICO art. 68', '184879'),
    (2690, 'SUB-2690', 'SBM5', '¿CUÁL ES EL DESTINO OBLIGATORIO DE LAS ACTAS DETALLADAS DE LAS DILIGENCIAS ESPECÍFICAS REALIZADAS POR LA POLICÍA NACIONAL DEL PERÚ, SEGÚN LA LEY MODIFICADA?:', 'SE ENTREGAN AL FISCAL A CARGO Y SE EMITE INFORME POLICIAL CORRESPONDIENTE.', 'ART. ÚNICO art. 67', '184882'),
    (2691, 'SUB-2691', 'SBM5', 'RESPECTO A LA MODIFICACIÓN INTRODUCIDA EN EL CÓDIGO PROCESAL PENAL, ¿QUÉ SUCEDE SI EL DECLARANTE NO CUENTA CON ABOGADO DEFENSOR DE ELECCIÓN O DEFENSOR PÚBLICO EN SU MANIFESTACIÓN ANTE LA POLICÍA NACIONAL DEL PERÚ?:', 'SE SUSPENDE LA DILIGENCIA Y SE REPROGRAMA.', 'ART. ÚNICO art. 68', '184883'),
    (2692, 'SUB-2692', 'SBM5', 'SEGÚN EL ARTÍCULO 84 DEL CÓDIGO PROCESAL PENAL, MODIFICADO POR LA LEY 32130, RESPECTO AL ACCESO DEL ABOGADO DEFENSOR A LA INFORMACIÓN DEL PROCESO, SEÑALE LA RESPUESTA CORRECTA:', 'EL ABOGADO DEFENSOR TIENE DERECHO A ACCEDER A LOS DOCUMENTOS DE ÁMBITO POLICIAL, FISCAL Y JUDICIAL EN TODO EL DESARROLLO DEL PROCESO, SIN MÁS LIMITACIÓN QUE LA PREVISTA EN LA LEY.', 'ART. ÚNICO art. 84', '184884'),
    (2693, 'SUB-2693', 'SBM5', 'EN CUANTO A LA OBTENCIÓN DE COPIAS SIMPLES DE LAS ACTUACIONES PROCESALES, CONFORME AL ARTÍCULO 84 MODIFICADO POR LA LEY 32130, ¿QUÉ DISPOSICIÓN SE APLICA AL ABOGADO DEFENSOR?', 'EL DERECHO DEL ABOGADO DEFENSOR A OBTENER COPIAS SIMPLES DE LAS ACTUACIONES ES PROCEDENTE EN CUALQUIER ESTADO O GRADO DEL PROCEDIMIENTO.', 'ART. ÚNICO art. 84', '184885'),
    (2694, 'SUB-2694', 'SBM5', 'DE ACUERDO CON EL ARTÍCULO 84 DEL CÓDIGO PROCESAL PENAL, TRAS LA REFORMA INTRODUCIDA POR LA LEY 32130, ¿CUÁL SERÍA EL LÍMITE AL DERECHO DEL ABOGADO DEFENSOR A ACCEDER A LA INFORMACIÓN DEL PROCESO?', 'LA ESTABLECIDA POR LA PROPIA LEY.', 'ART. ÚNICO art. 84', '184886'),
    (2695, 'SUB-2695', 'SBM5', 'SEGÚN LA MODIFICACIÓN DEL ARTÍCULO 160 DEL CÓDIGO PROCESAL PENAL INTRODUCIDA POR LA LEY 32130 (ARTÍCULO ÚNICO), ¿EN CUÁL DE LAS SIGUIENTES SITUACIONES LA CONFESIÓN DE UN IMPUTADO TIENE VALOR PROBATORIO EN EL PROCESO PENAL?:', 'CUANDO EL IMPUTADO CONFIESA ANTE EL FISCAL O JUEZ, CON PRESENCIA DE SU ABOGADO DEFENSOR, Y DICHA DILIGENCIA ES REGISTRADA EN EQUIPOS AUDIOVISUALES.', 'ART. ÚNICO art. 160', '184887'),
    (2696, 'SUB-2696', 'SBM5', 'EN VIRTUD DE LA REDACCIÓN ACTUAL DEL ARTÍCULO 160 DEL CÓDIGO PROCESAL PENAL, TRAS LA ENTRADA EN VIGENCIA DE LA LEY 32130, ¿CUÁL SERÍA EL EFECTO PROBATORIO DE UNA CONFESIÓN OBTENIDA POR LA POLICÍA NACIONAL EN ETAPA DE INVESTIGACIÓN PRELIMINAR SIN LA PRESENCIA DEL ABOGADO DEFENSOR, AUNQUE ESTUVIERA GRABADA POR EQUIPOS AUDIOVISUALES?:', 'CARECERÍA DE VALOR PROBATORIO POR OMITIR LA PRESENCIA DEL ABOGADO DEFENSOR, AÚN EXISTIENDO REGISTRO AUDIOVISUAL.', 'ART. ÚNICO art. 160', '184888'),
    (2697, 'SUB-2697', 'SBM5', 'SEGÚN EL ARTÍCULO 173 MODIFICADO POR LA LEY 32130, ¿CUÁL ES LA ENTIDAD QUE, DE MANERA PRIORITARIA Y SIN NECESIDAD DE DESIGNACIÓN EXPRESA, TIENE A SU CARGO LA REALIZACIÓN DE EXÁMENES O PERICIAS CRIMINALÍSTICAS EN TODA INVESTIGACIÓN PENAL?:', 'LA DIRECCIÓN DE CRIMINALÍSTICA DE LA POLICÍA NACIONAL DEL PERÚ O SUS OFICINAS DESCENTRALIZADAS. Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', 'ART. ÚNICO art. 173', '184889'),
    (2698, 'SUB-2698', 'SBM5', '¿EN QUÉ CIRCUNSTANCIA SE PUEDE ENCOMENDAR LA PERICIA CRIMINALÍSTICA OFICIAL A ENTIDADES DISTINTAS A LA DIRECCIÓN DE CRIMINALÍSTICA DE LA PNP SEGÚN LA NORMATIVA REFERIDA?:', 'EN EL CASO DE QUE LA DIRECCIÓN DE CRIMINALÍSTICA DE LA PNP CAREZCA DE PERITOS O DE MATERIAL DE LABORATORIO O INSUMOS NECESARIOS.', 'ART. ÚNICO art. 173', '184890'),
    (2699, 'SUB-2699', 'SBM5', '¿ES CORRECTO AFIRMAR QUE LA LABOR PERICIAL PUEDE SER ENCOMENDADA A ORGANISMOS DEL ESTADO QUE DESARROLLAN LABOR CIENTÍFICA O TÉCNICA, Y BAJO QUÉ CONDICIÓN PRINCIPAL SEGÚN EL ARTÍCULO 173?:', 'SÍ, SIEMPRE QUE REUNAN LAS CUALIDADES NECESARIAS PARA TAL FIN, CON CONOCIMIENTO DE LAS PARTES.', 'ART. ÚNICO art. 173', '184891'),
    (2700, 'SUB-2700', 'SBM5', 'SEGÚN EL ARTÍCULO 173, ¿QUÉ CARACTERÍSTICA DESCRIBE LA PRESTACIÓN DEL AUXILIO PERICIAL POR PARTE DE LAS ENTIDADES ESTATALES CIENTÍFICAS O TÉCNICAS?', 'ES GRATUITA, CONFORME AL MANDATO LEGAL.', 'ART. ÚNICO art. 173', '184893')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

