    ('SUB-2661', 'A', 'LA INVESTIGACIÓN POLICIAL TIENE CARÁCTER JURISDICCIONAL PLENO DESDE SU INICIO, PERMITIENDO A LA POLICÍA NACIONAL RESOLVER ASPECTOS SUSTANTIVOS DEL PROCESO PENAL.', FALSE, 1),
    ('SUB-2661', 'B', 'LA INVESTIGACIÓN POLICIAL, BAJO LA CONDUCCIÓN DEL MINISTERIO PÚBLICO, ADQUIERE CARÁCTER JURISDICCIONAL ÚNICAMENTE EN CASOS DE FLAGRANCIA DELICTIVA.', FALSE, 2),
    ('SUB-2661', 'C', 'LA INVESTIGACIÓN POLICIAL, BAJO CONDUCCIÓN DEL MINISTERIO PÚBLICO, NO TIENE CARÁCTER JURISDICCIONAL, DEBIENDO REQUERIRSE DECISIÓN JURISDICCIONAL AL ÓRGANO COMPETENTE CUANDO SEA INDISPENSABLE.', TRUE, 3),
    ('SUB-2661', 'D', 'LA INVESTIGACIÓN POLICIAL ES DE NATURALEZA JURISDICCIONAL SOLO CUANDO INTERVIENEN PERITOS EXTERNOS DESIGNADOS POR EL JUEZ PENAL.', FALSE, 4),
    ('SUB-2661', 'E', 'LA INVESTIGACIÓN POLICIAL Y LA FISCALÍA COMPARTEN COMPETENCIA JURISDICCIONAL EN IGUALDAD DE CONDICIONES DURANTE TODA LA ETAPA DE INVESTIGACIÓN PRELIMINAR.', FALSE, 5),
    ('SUB-2662', 'A', 'EMITIR RESOLUCIONES JURISDICCIONALES REEMPLAZANDO AL JUEZ PENAL EN ACTOS DE URGENCIA.', FALSE, 1),
    ('SUB-2662', 'B', 'DIRIGIR JURÍDICAMENTE LA INVESTIGACIÓN ORIENTANDO LEGALMENTE LAS ACCIONES DE LA POLICÍA NACIONAL DEL PERÚ DENTRO DE LOS PARÁMETROS DE LA LEY', TRUE, 2),
    ('SUB-2662', 'C', 'REALIZAR DE MANERA INDEPENDIENTE LA INTERVENCIÓN POLICIAL SIN COORDINACIÓN INTERINSTITUCIONAL.', FALSE, 3),
    ('SUB-2662', 'D', 'SUPERVISAR ÚNICAMENTE LA RECOLECCIÓN DE PRUEBAS FÍSICAS Y DOCUMENTALES SIN INDAGAR SOBRE LA INOCENCIA DEL IMPUTADO.', FALSE, 4),
    ('SUB-2662', 'E', 'DESIGNAR A LOS ABOGADOS DEFENSORES PÚBLICOS EN TODOS LOS CASOS QUE INVESTIGUE LA POLICÍA.', FALSE, 5),
    ('SUB-2663', 'A', 'COMPARTIR LA CARGA DE LA PRUEBA CON EL IMPUTADO EN LA INVESTIGACIÓN PRELIMINAR.', FALSE, 1),
    ('SUB-2663', 'B', 'RECABAR LA MAYOR CANTIDAD DE ELEMENTOS PROBATORIOS, SIN IMPORTAR SI DETERMINAN INOCENCIA O CULPABILIDAD DEL IMPUTADO, Y ASUMIR EXCLUSIVAMENTE LA DEFENSA DE LA VÍCTIMA.', FALSE, 2),
    ('SUB-2663', 'C', 'ASUMIR LA CARGA DE LA PRUEBA. ACTUANDO CON OBJETIVIDAD, INDAGANDO POR INTERMEDIO DE LA POLICIA TANTO HECHOS CONSTITUTIVOS DEL DELITO, QUE DETERMINEN LA RESPONSABILIDAD O INOCENCIA DEL IMPUTADO.', TRUE, 3),
    ('SUB-2663', 'D', 'LIMITAR LA CARGA DE LA PRUEBA SOLO A LOS HECHOS PRESENTADOS POR LA ACUSACIÓN PARTICULAR.', FALSE, 4),
    ('SUB-2663', 'E', 'DELEGAR LA CARGA DE LA PRUEBA EN SU TOTALIDAD EN LA POLICÍA NACIONAL DEL PERÚ.', FALSE, 5),
    ('SUB-2664', 'A', 'CUANDO SE TRATE DE ACTOS DE INVESTIGACIÓN QUE INVOLUCREN MENORES DE EDAD, INDEPENDIENTEMENTE DEL TIPO DE DELITO.', FALSE, 1),
    ('SUB-2664', 'B', 'SOLO CUANDO LA POLICÍA NACIONAL NO CUENTE CON LOS RECURSOS MATERIALES PARA CONTINUAR LA INVESTIGACIÓN PRELIMINAR.', FALSE, 2),
    ('SUB-2664', 'C', 'SIEMPRE QUE SE REQUIERA UNA DECISIÓN DE NATURALEZA JURISDICCIONAL QUE EXCEDA LAS COMPETENCIAS LEGALES, MOTIVANDO DEBIDAMENETE SU PETICIÓN.', TRUE, 3),
    ('SUB-2664', 'D', 'AL INICIO DE TODA INVESTIGACIÓN PRELIMINAR, SIN EXCLUSIÓN DE ACTOS JURÍDICOS POSTERIORES.', FALSE, 4),
    ('SUB-2664', 'E', 'CUANDO EL DELITO INVESTIGADO INVOLUCRE FUNCIONARIOS PÚBLICOS BAJO RESERVA DE LEY.', FALSE, 5),
    ('SUB-2665', 'A', 'LA POLICÍA NACIONAL DIRIGE AUTÓNOMAMENTE LA INVESTIGACIÓN Y EL MINISTERIO PÚBLICO SOLO REVISA EL INFORME FINAL.', FALSE, 1),
    ('SUB-2665', 'B', 'LA POLICÍA NACIONAL EJERCE INICIATIVA PLENA EN LA PRODUCCIÓN DE PRUEBAS Y EL MINISTERIO PÚBLICO SE LIMITA A AUTORIZARLAS RETROACTIVAMENTE', FALSE, 2),
    ('SUB-2665', 'C', 'EL MINISTERIO PÚBLICO ASUME LA CONDUCCIÓN JURÍDICA DE LA INVESTIGACIÓN Y LA POLICÍA NACIONAL REALIZA LA INVESTIGACIÓN PRELIMINAR CONFORME A SU LEYES Y REGLAMENTOS.', TRUE, 3),
    ('SUB-2665', 'D', 'AMBOS ÓRGANOS ACTÚAN EN PIE DE IGUALDAD EN LA TOMA DE DECISIONES JURÍDICAS DURANTE LA INVESTIGACIÓN PRELIMINAR.', FALSE, 4),
    ('SUB-2665', 'E', 'LA POLICÍA NACIONAL SOLO INTERVIENE CUANDO EL JUEZ PENAL LO AUTORIZA, ACTUANDO BAJO CONTROL JUDICIAL DIRECTO.', FALSE, 5),
    ('SUB-2666', 'A', 'QUE EL JUEZ HAYA MANIFESTADO SU OPINIÓN SOBRE LA CAUSA A UNA DE LAS PARTES DEL PROCESO DE MODO CONFIDENCIAL.', FALSE, 1),
    ('SUB-2666', 'B', 'QUE EL JUEZ HAYA PARTICIPADO PREVIAMENTE COMO ABOGADO DEFENSOR EN UNA CAUSA SIMILAR.', FALSE, 2),
    ('SUB-2666', 'C', 'QUE EL JUEZ TENGA PARENTESCO CON UNO DE LOS TESTIGOS DEL PROCESO.', FALSE, 3),
    ('SUB-2666', 'D', 'QUE EL JUEZ HAYA ACONSEJADO SOBRE LA CAUSA A CUALQUIERA DE LAS PARTES DEL PROCESO, AFECTANDO POTENCIALMENTE SU IMPARCIALIDAD.', TRUE, 4),
    ('SUB-2666', 'E', 'QUE EL JUEZ HAYA INTERPRETADO UN ARTÍCULO DEL CÓDIGO PENAL PARA EFECTOS DOCTRINARIOS EN UNA REVISTA ESPECIALIZADA.', FALSE, 5),
    ('SUB-2667', 'A', 'LA INHIBICIÓN DE FISCALES SOLO SE APLICA SI HAN ACTUADO COMO ABOGADOS EN UNA CAUSA CONEXA', FALSE, 1),
    ('SUB-2667', 'B', 'LA DISPOSICIÓN SOBRE INHIBICIÓN DE FISCALES APLICA ÚNICAMENTE SI EXISTE PRUEBA DOCUMENTAL DE PARCIALIDAD.', FALSE, 2),
    ('SUB-2667', 'C', 'LA FALTA COMETIDA POR LOS FISCALES QUE INCURREN EN LAS CAUSALES DE INHIBICIÓN ES CONSIDERADA FALTA LEVE SEGÚN LA LEY 29277.', FALSE, 3),
    ('SUB-2667', 'D', 'DICHA INHIBICIÓN ALCANZA A LOS FISCALES EN LOS MISMOS TÉRMINOS QUE A LOS JUECES Y SU INOBSERVANCIA CONSTITUYE FALTA MUY GRAVE SEGÚN LA LEY 29277.', TRUE, 4),
    ('SUB-2667', 'E', 'NO SE EXIGE FUNDAMENTO PARA LA INHIBICIÓN DE FISCALES, BASTA LA SIMPLE SOSPECHA DE IMPARCIALIDAD.', FALSE, 5),
    ('SUB-2668', 'A', 'PUEDE SER INTERPUESTA HASTA ANTES DE LA NOTIFICACIÓN DE LA SENTENCIA, SIENDO EL ÓRGANO REVISOR QUIEN TIENE LA OBLIGACIÓN DE CONCEDER DOS DÍAS DE PLAZO A LAS PARTES PARA EJERCER EL DERECHO DE RECUSACIÓN.', FALSE, 1),
    ('SUB-2668', 'B', 'DEBE SER INTERPUESTA HASTA UN DÍA HÁBIL ANTES DE LA AUDIENCIA DE VISTA DE LA CAUSA Y EL ÓRGANO REVISOR DEBE CONCEDER EL PLAZO DE TRES DÍAS A LAS PARTES PARA RECUSAR A LOS JUECES DE REVISIÓN.', TRUE, 2),
    ('SUB-2668', 'C', 'LA RECUSACIÓN PUEDE INTERPONERSE EN CUALQUIER MOMENTO ANTES DEL PRONUNCIAMIENTO DEL JUZGADO DE EJECUCIÓN, QUEDANDO FACULTADO EL ÓRGANO REVISOR PARA DEFINIR EL PLAZO RESPECTIVO.', FALSE, 3),
    ('SUB-2668', 'D', 'ES VÁLIDA SOLO CUANDO SE INTERPONE AL INICIO DE LA AUDIENCIA, DEBIENDO EL ÓRGANO REVISOR CONCEDER CINCO DÍAS CONSECUTIVOS A LAS PARTES PARA FUNDAMENTAR LA RECUSACIÓN.', FALSE, 4),
    ('SUB-2668', 'E', 'LA RECUSACIÓN SÓLO PUEDE PLANTEARSE DURANTE LA AUDIENCIA DE VISTA DE LA CAUSA, Y EL ÓRGANO REVISOR ESTÁ OBLIGADO A RESOLVER DE INMEDIATO SIN OTORGAR PLAZO ADICIONAL A LAS PARTES.', FALSE, 5),
    ('SUB-2669', 'A', 'EL JUEZ QUE NO SE INHIBE DE OFICIO INCURRIRÁ EN UNA FALTA ADMINISTRATIVA LEVE PREVISTA EN LA LEY ORGÁNICA DEL PODER JUDICIAL.', FALSE, 1),
