    ('SUB-2700', 'A', 'ES REMUNERADA SEGÚN ARANCEL ESTABLECIDO.', FALSE, 1),
    ('SUB-2700', 'B', 'ES GRATUITA, CONFORME AL MANDATO LEGAL.', TRUE, 2),
    ('SUB-2700', 'C', 'ES SUJETA A COSTOS DETERMINADOS POR LA POLICÍA NACIONAL.', FALSE, 3),
    ('SUB-2700', 'D', 'IMPLICA UN REINTEGRO ECONÓMICO POSTERIOR A LA SENTENCIA.', FALSE, 4),
    ('SUB-2700', 'E', 'ES ASUMIDA EXCLUSIVAMENTE POR LA PARTE INTERESADA EN LA PERICIA.', FALSE, 5)
)
INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

COMMIT;
